import { Switch, Route } from "wouter";
import { queryClient } from "./lib/queryClient";
import { QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { ThemeProvider } from "@/components/theme-provider";
import { ThemeToggle } from "@/components/theme-toggle";
import { SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { AppSidebar } from "@/components/app-sidebar";
import NotFound from "@/pages/not-found";
import Dashboard from "@/pages/dashboard";
import Methodology from "@/pages/methodology";
import ClimateValuation from "@/pages/climate-valuation";
import DecarbSignal from "@/pages/decarb-signal";
import DecarbGapSignal from "@/pages/decarb-gap-signal";
import NewsSentiment from "@/pages/news-sentiment";
import DataManagement from "@/pages/data-management";
import { ValuationNotice } from "@/components/valuation-notice";

function Router() {
  return (
    <Switch>
      <Route path="/" component={Dashboard} />
      <Route path="/methodology" component={Methodology} />
      <Route path="/climate-valuation" component={ClimateValuation} />
      <Route path="/decarb-signal" component={DecarbSignal} />
      <Route path="/decarb-gap" component={DecarbGapSignal} />
      <Route path="/news-sentiment" component={NewsSentiment} />
      <Route path="/data-management" component={DataManagement} />
      <Route component={NotFound} />
    </Switch>
  );
}

function App() {
  const style = {
    "--sidebar-width": "14rem",
    "--sidebar-width-icon": "3rem",
  };

  return (
    <ThemeProvider>
      <QueryClientProvider client={queryClient}>
        <TooltipProvider>
          <SidebarProvider style={style as React.CSSProperties}>
            <div className="flex h-screen w-full">
              <AppSidebar />
              <div className="flex flex-col flex-1 overflow-hidden">
                <header className="flex items-center justify-between gap-2 p-2 border-b sticky top-0 z-50 bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
                  <SidebarTrigger data-testid="button-sidebar-toggle" />
                  <ThemeToggle />
                </header>
                <main className="flex-1 overflow-auto">
                  <ValuationNotice />
                  <Router />
                </main>
              </div>
            </div>
          </SidebarProvider>
          <Toaster />
        </TooltipProvider>
      </QueryClientProvider>
    </ThemeProvider>
  );
}

export default App;

import { BarChart3, BookOpen, DollarSign, Activity, Newspaper, ArrowLeftRight, Database } from "lucide-react";
import { useLocation, Link } from "wouter";

import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarHeader,
  SidebarFooter,
} from "@/components/ui/sidebar";

const menuItems = [
  {
    title: "Dashboard",
    url: "/",
    icon: BarChart3,
  },
  {
    title: "Methodology",
    url: "/methodology",
    icon: BookOpen,
  },
  {
    title: "Scenario Analyzer",
    url: "/climate-valuation",
    icon: DollarSign,
  },
  {
    title: "Decarb Signal",
    url: "/decarb-signal",
    icon: Activity,
  },
  {
    title: "Decarb Gap",
    url: "/decarb-gap",
    icon: ArrowLeftRight,
  },
  {
    title: "News Sentiment",
    url: "/news-sentiment",
    icon: Newspaper,
  },
  {
    title: "Data Management",
    url: "/data-management",
    icon: Database,
  },
];

export function AppSidebar() {
  const [location] = useLocation();

  return (
    <Sidebar>
      <SidebarHeader className="p-4">
        <div className="flex items-center gap-2">
          <div className="flex items-center justify-center w-8 h-8 rounded-md bg-primary/10">
            <BarChart3 className="h-4 w-4 text-primary" />
          </div>
          <div>
            <p className="text-sm font-semibold" data-testid="text-sidebar-title">Climate Dashboard</p>
            <p className="text-[10px] text-muted-foreground" data-testid="text-sidebar-subtitle">Decarbonization Tracker</p>
          </div>
        </div>
      </SidebarHeader>

      <SidebarContent>
        <SidebarGroup>
          <SidebarGroupLabel>Navigation</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {menuItems.map((item) => (
                <SidebarMenuItem key={item.title}>
                  <SidebarMenuButton
                    asChild
                    isActive={location === item.url}
                    data-testid={`link-sidebar-${item.title.toLowerCase()}`}
                  >
                    <Link href={item.url}>
                      <item.icon />
                      <span>{item.title}</span>
                    </Link>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter className="p-4">
        <p className="text-[10px] text-muted-foreground leading-relaxed">
          Data: IEA, IRENA, SBTi, Gallup, Pew Research, Climate Action Tracker
        </p>
      </SidebarFooter>
    </Sidebar>
  );
}

import type { BacktestResponse } from "@shared/backtest";

export async function fetchBacktest(url: string): Promise<BacktestResponse> {
  const response = await fetch(url, { credentials: "include" });
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || "Backtest request failed");
  return body;
}

export function BacktestSummary({ data, error, label }: {
  data?: BacktestResponse; error?: Error | null; label?: string;
}) {
  if (error) return <p role="alert" className="text-sm text-destructive mb-3">{label}: {error.message}</p>;
  if (!data) return null;
  const s = data.summary;
  return (
    <div className="text-xs text-muted-foreground space-y-1 mb-3" data-testid="backtest-calibration-summary">
      <p>
        {label && <strong>{label}: </strong>}
        Target TE {s.targetTrackingErrorPct.toFixed(2)}% · Realised full-period TE {s.realizedTrackingErrorPct?.toFixed(3) ?? "N/A"}%
        {" · "}{s.calibrationBasis === "expanding_past_only" ? "Latest tilt" : "Tilt"} {s.tiltScale?.toFixed(4) ?? "N/A"}
        {s.calibrationBasis === "expanding_past_only" && " · Initial training"}
        {s.calibrationPeriod && ` · ${s.calibrationPeriod.start}–${s.calibrationPeriod.end} (${s.calibrationPeriod.months} months)`}
        {" · "}Ranking: {s.method.replaceAll("_", " ")}
      </p>
      {s.calibrationStatus !== "within_tolerance" && <p role="status">Calibration: {s.calibrationStatus.replaceAll("_", " ")}. Target TE is not guaranteed.</p>}
      {s.warnings.map(warning => <p key={warning}>{warning}</p>)}
      {s.accounting && <p>
        Cost assumption: {s.accounting.costBps} bps per traded dollar · Gross cumulative return: {((s.accounting.grossCumulative - 1) * 100).toFixed(2)}%
        {" · "}Net cumulative return: {((s.accounting.netCumulative - 1) * 100).toFixed(2)}%
        {" · "}Maximum net drawdown: {(s.accounting.maxNetDrawdown * 100).toFixed(2)}%
        {" · "}Total one-way turnover: {s.accounting.totalTurnover.toFixed(2)}×
      </p>}
      <p>The TE series is annualised over the expanding history, not a rolling fixed-length window.</p>
    </div>
  );
}

import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Zap, Shield, Building2, Users } from "lucide-react";
import type { CategoryProjectionResult } from "@/lib/types";
import { DownloadDataButton } from "@/components/download-data-button";

interface CategoryComparisonProps {
  categories: CategoryProjectionResult[];
  isLoading?: boolean;
}

function getCategoryIcon(category: string) {
  switch (category) {
    case "technology": return Zap;
    case "policy": return Shield;
    case "corporate": return Building2;
    case "socioeconomic": return Users;
    default: return Zap;
  }
}

function getCategoryColor(category: string): string {
  switch (category) {
    case "technology": return "hsl(168, 76%, 36%)";
    case "policy": return "hsl(43, 86%, 42%)";
    case "corporate": return "hsl(27, 87%, 48%)";
    case "socioeconomic": return "hsl(340, 65%, 50%)";
    default: return "hsl(168, 76%, 36%)";
  }
}

function getTempColor(temp: number): string {
  if (temp <= 1.5) return "text-emerald-500";
  if (temp <= 2.0) return "text-sky-500";
  if (temp <= 2.5) return "text-amber-500";
  if (temp <= 3.0) return "text-orange-500";
  return "text-red-500";
}

export function CategoryComparison({ categories, isLoading }: CategoryComparisonProps) {
  if (isLoading) {
    return (
      <Card className="p-6">
        <Skeleton className="h-6 w-48 mb-4" />
        <div className="grid grid-cols-2 gap-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <Skeleton key={i} className="h-24" />
          ))}
        </div>
      </Card>
    );
  }

  const downloadRows = categories.map((c) => ({
    Category: c.categoryName,
    "Temperature (\u00B0C)": c.temperatureRise,
    "Reduction Rate (%/yr)": c.reductionRate,
    "Net-Zero Year": c.netZeroYear ?? "Never",
  }));

  return (
    <Card className="p-6" data-testid="card-category-comparison">
      <div className="mb-4 flex items-start justify-between gap-2 flex-wrap">
        <div>
          <h3 className="text-sm font-medium text-muted-foreground">Category Scenario Analysis</h3>
          <p className="text-xs text-muted-foreground mt-0.5">
            Illustrative input-shock scenarios, not forecasts or category contributions.
            The full model evolves in each case; the socioeconomic scenario also changes policy and corporate inputs.
            See Methodology for exact shocks and baseline differences.
          </p>
        </div>
        <DownloadDataButton
          filename="category-scenario-analysis"
          sheetName="Category Scenarios"
          rows={downloadRows}
          testId="button-download-category-scenarios"
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {categories.map((cat) => {
          const Icon = getCategoryIcon(cat.category);
          const color = getCategoryColor(cat.category);

          return (
            <Card key={cat.category} className="p-4 hover-elevate" data-testid={`card-category-impact-${cat.category}`}>
              <div className="flex items-center gap-2 mb-3">
                <div
                  className="flex items-center justify-center w-8 h-8 rounded-md"
                  style={{ backgroundColor: `${color}20` }}
                >
                  <Icon className="h-4 w-4" style={{ color }} />
                </div>
                <div>
                  <p className="text-sm font-medium">{cat.categoryName}</p>
                  <p className="text-[10px] text-muted-foreground">Stylized scenario</p>
                </div>
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Temperature</span>
                  <span className={`text-sm font-bold tabular-nums ${getTempColor(cat.temperatureRise)}`} data-testid={`text-category-temp-${cat.category}`}>
                    {cat.temperatureRise.toFixed(2)}&deg;C
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Reduction Rate</span>
                  <span className="text-sm font-semibold tabular-nums" data-testid={`text-category-rate-${cat.category}`}>
                    {cat.reductionRate.toFixed(2)}%/yr
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Net-Zero</span>
                  <span className="text-sm font-semibold tabular-nums" data-testid={`text-category-netzero-${cat.category}`}>
                    {cat.netZeroYear || "Never"}
                  </span>
                </div>
              </div>
            </Card>
          );
        })}
      </div>
    </Card>
  );
}

import { Button } from "@/components/ui/button";
import { Zap, Shield, Building2, Users, Globe, Banknote, Activity } from "lucide-react";
import type { Category } from "@/lib/types";

interface CategoryFilterProps {
  activeCategory: Category;
  onCategoryChange: (category: Category) => void;
}

const CATEGORIES: { value: Category; label: string; icon: React.ElementType; description: string }[] = [
  { value: "all", label: "All Factors", icon: Globe, description: "Combined impact of all factors" },
  { value: "technology", label: "Technology", icon: Zap, description: "Renewables + EVs only" },
  { value: "policy", label: "Policy", icon: Shield, description: "Government action only" },
  { value: "corporate", label: "Corporate", icon: Building2, description: "SBTi targets only" },
  { value: "socioeconomic", label: "Socioeconomic", icon: Users, description: "Public opinion impact" },
  { value: "financial", label: "Financial", icon: Banknote, description: "Investment flows + divestment" },
  { value: "emissions", label: "Emissions", icon: Activity, description: "Observed emissions validation" },
];

export function CategoryFilter({ activeCategory, onCategoryChange }: CategoryFilterProps) {
  return (
    <div className="flex items-center gap-2 flex-wrap" data-testid="filter-category">
      {CATEGORIES.map((cat) => {
        const Icon = cat.icon;
        const isActive = activeCategory === cat.value;
        return (
          <Button
            key={cat.value}
            variant={isActive ? "default" : "outline"}
            size="sm"
            onClick={() => onCategoryChange(cat.value)}
            className="gap-1.5"
            data-testid={`button-category-${cat.value}`}
          >
            <Icon className="h-3.5 w-3.5" />
            {cat.label}
          </Button>
        );
      })}
    </div>
  );
}

import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  ReferenceLine,
} from "recharts";
import type { CategoryHistoricalTrendPoint, MetricView } from "@/lib/types";
import { DownloadDataButton } from "@/components/download-data-button";

interface CategoryTrendChartProps {
  data: CategoryHistoricalTrendPoint[];
  metricView: MetricView;
  isLoading?: boolean;
}

const CATEGORY_KEYS = ["all", "technology", "policy", "corporate", "socioeconomic", "financial", "emissions"] as const;

const CATEGORY_COLORS: Record<string, string> = {
  all: "hsl(var(--muted-foreground))",
  technology: "hsl(168, 76%, 36%)",
  policy: "hsl(43, 86%, 42%)",
  corporate: "hsl(27, 87%, 48%)",
  socioeconomic: "hsl(340, 65%, 50%)",
  financial: "hsl(150, 65%, 40%)",
  emissions: "hsl(0, 65%, 50%)",
};

const CATEGORY_NAMES: Record<string, string> = {
  all: "All (Baseline)",
  technology: "Technology",
  policy: "Policy",
  corporate: "Corporate",
  socioeconomic: "Socioeconomic",
  financial: "Financial Flows",
  emissions: "Emissions",
};

function getConfig(metricView: MetricView) {
  switch (metricView) {
    case "temperature":
      return {
        title: "Category Scenario Temperature Trends",
        subtitle: "Projected temperature rise under each what-if scenario over time",
        metricKey: "median" as const,
        yLabel: "\u00B0C above pre-industrial",
        yDomain: undefined as [number, number] | undefined,
        formatter: (v: number) => `${v.toFixed(2)}\u00B0C`,
        referenceLines: [
          { y: 1.5, label: "1.5\u00B0C", color: "hsl(168, 76%, 36%)" },
          { y: 2.0, label: "2.0\u00B0C", color: "hsl(197, 71%, 38%)" },
        ],
      };
    case "reductionRate":
      return {
        title: "Category Scenario Reduction Rates",
        subtitle: "Projected emissions reduction rate under each scenario",
        metricKey: "reductionRate" as const,
        yLabel: "% per year",
        yDomain: undefined as [number, number] | undefined,
        formatter: (v: number) => `${v.toFixed(2)}%/yr`,
        referenceLines: [
          { y: 7.0, label: "1.5\u00B0C pathway", color: "hsl(168, 76%, 36%)" },
        ],
      };
    case "netZero":
      return {
        title: "Category Scenario Net-Zero Year",
        subtitle: "Projected net-zero year under each scenario",
        metricKey: "netZeroYear" as const,
        yLabel: "Net-Zero Year",
        yDomain: [2050, 2200] as [number, number],
        formatter: (v: number) => `${Math.round(v)}`,
        referenceLines: [
          { y: 2050, label: "2050 Target", color: "hsl(168, 76%, 36%)" },
        ],
      };
  }
}

export function CategoryTrendChart({ data, metricView, isLoading }: CategoryTrendChartProps) {
  if (isLoading) {
    return (
      <Card className="p-6">
        <Skeleton className="h-6 w-48 mb-4" />
        <Skeleton className="h-[280px] w-full" />
      </Card>
    );
  }

  if (!data.length) return null;

  const config = getConfig(metricView);
  const hasNowcast = data.some((d) => d.isNowcast);

  const downloadRows = data.map((d) => {
    const row: Record<string, string | number | boolean | undefined> = {
      Year: d.year,
      Estimated: d.isNowcast ? "yes" : "no",
    };
    for (const key of CATEGORY_KEYS) {
      let value: number | null | undefined = d[key][config.metricKey];
      if (config.metricKey === "netZeroYear" && value === null) value = 2200;
      row[CATEGORY_NAMES[key]] = value ?? undefined;
    }
    return row;
  });

  const chartData = data.map((d) => {
    const row: Record<string, number | string | boolean | undefined> = { year: d.year, isNowcast: d.isNowcast };
    for (const key of CATEGORY_KEYS) {
      const metrics = d[key];
      let value = metrics[config.metricKey];
      if (config.metricKey === "netZeroYear" && value === null) {
        value = 2200;
      }
      row[key] = d.isNowcast ? undefined : (value ?? undefined);
      row[`${key}_nowcast`] = d.isNowcast ? (value ?? undefined) : undefined;
    }
    return row;
  });

  if (hasNowcast) {
    const lastObservedIdx = chartData.findIndex((d) => {
      const nextIdx = chartData.indexOf(d) + 1;
      return nextIdx < chartData.length && chartData[nextIdx].isNowcast;
    });
    if (lastObservedIdx >= 0) {
      for (const key of CATEGORY_KEYS) {
        chartData[lastObservedIdx][`${key}_nowcast`] = chartData[lastObservedIdx][key];
      }
    }
  }

  return (
    <Card className="p-6" data-testid="card-category-trend">
      <div className="mb-4 flex items-start justify-between gap-2 flex-wrap">
        <div>
          <div className="flex items-center gap-2 flex-wrap">
            <h3 className="text-sm font-medium text-muted-foreground">{config.title}</h3>
            {hasNowcast && (
              <Badge variant="secondary" className="text-[10px] px-1.5 py-0">
                Nowcast
              </Badge>
            )}
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">{config.subtitle}</p>
        </div>
        <DownloadDataButton
          filename={`category-trends-${metricView}`}
          sheetName="Category Trends"
          rows={downloadRows}
          testId="button-download-category-trends"
        />
      </div>

      <ResponsiveContainer width="100%" height={280}>
        <LineChart data={chartData} margin={{ top: 5, right: 10, left: 0, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
          <XAxis
            dataKey="year"
            stroke="hsl(var(--muted-foreground))"
            fontSize={11}
            tickLine={false}
            axisLine={false}
          />
          <YAxis
            stroke="hsl(var(--muted-foreground))"
            fontSize={11}
            tickLine={false}
            axisLine={false}
            domain={config.yDomain}
            label={{
              value: config.yLabel,
              angle: -90,
              position: "insideLeft",
              style: { fontSize: 11, fill: "hsl(var(--muted-foreground))" },
            }}
          />
          <Tooltip
            content={({ active, payload, label }) => {
              if (!active || !payload?.length) return null;
              const point = payload[0]?.payload;
              const isNc = point?.isNowcast;
              return (
                <div
                  style={{
                    backgroundColor: "hsl(var(--card))",
                    border: "1px solid hsl(var(--border))",
                    borderRadius: "6px",
                    fontSize: "12px",
                    padding: "8px 12px",
                  }}
                >
                  <p className="text-xs text-muted-foreground mb-1.5">
                    {isNc ? `${label} (estimated)` : `${label}`}
                  </p>
                  {CATEGORY_KEYS.map((key) => {
                    const val = isNc ? point[`${key}_nowcast`] : point[key];
                    if (val == null) return null;
                    return (
                      <div key={key} className="flex items-center justify-between gap-4">
                        <div className="flex items-center gap-1.5">
                          <div
                            className="w-2.5 h-2.5 rounded-sm"
                            style={{ backgroundColor: CATEGORY_COLORS[key] }}
                          />
                          <span className="text-xs">{CATEGORY_NAMES[key]}</span>
                        </div>
                        <span className="text-xs font-medium tabular-nums">
                          {config.formatter(val as number)}
                        </span>
                      </div>
                    );
                  })}
                </div>
              );
            }}
          />
          {config.referenceLines.map((ref, i) => (
            <ReferenceLine
              key={i}
              y={ref.y}
              stroke={ref.color}
              strokeDasharray="4 4"
              label={{
                value: ref.label,
                position: "insideTopRight",
                style: { fontSize: 10, fill: ref.color },
              }}
            />
          ))}
          {CATEGORY_KEYS.map((key) => (
            <Line
              key={key}
              type="monotone"
              dataKey={key}
              stroke={CATEGORY_COLORS[key]}
              strokeWidth={key === "all" ? 2.5 : 1.5}
              strokeDasharray={key === "all" ? "6 3" : undefined}
              dot={false}
              activeDot={{ r: 3 }}
              connectNulls={false}
            />
          ))}
          {hasNowcast && CATEGORY_KEYS.map((key) => (
            <Line
              key={`${key}_nowcast`}
              type="monotone"
              dataKey={`${key}_nowcast`}
              stroke={CATEGORY_COLORS[key]}
              strokeWidth={key === "all" ? 2 : 1.5}
              strokeDasharray="4 3"
              dot={false}
              activeDot={{ r: 3 }}
              connectNulls={false}
            />
          ))}
        </LineChart>
      </ResponsiveContainer>

      <div className="flex items-center justify-center gap-3 mt-2 flex-wrap">
        {CATEGORY_KEYS.map((key) => (
          <div key={key} className="flex items-center gap-1">
            <div
              className="w-3 h-0.5"
              style={{
                backgroundColor: CATEGORY_COLORS[key],
                borderTop: key === "all" ? `2px dashed ${CATEGORY_COLORS[key]}` : undefined,
              }}
            />
            <span className="text-[10px] text-muted-foreground">{CATEGORY_NAMES[key]}</span>
          </div>
        ))}
      </div>
    </Card>
  );
}

import { useState } from "react";
import { Download } from "lucide-react";
import { Button } from "@/components/ui/button";

type Cell = string | number | boolean | null | undefined;
export type DownloadRow = Record<string, Cell>;

interface DownloadDataButtonProps {
  filename: string;
  rows: DownloadRow[] | (() => DownloadRow[]);
  sheetName?: string;
  label?: string;
  disabled?: boolean;
  className?: string;
  testId?: string;
}

export function DownloadDataButton({
  filename,
  rows,
  sheetName = "Data",
  label = "Download data",
  disabled,
  className,
  testId = "button-download-data",
}: DownloadDataButtonProps) {
  const [busy, setBusy] = useState(false);

  const resolvedEmpty = typeof rows === "function" ? false : !rows || rows.length === 0;

  const handleClick = async () => {
    const data = typeof rows === "function" ? rows() : rows;
    if (!data || data.length === 0) return;
    setBusy(true);
    try {
      const XLSX = await import("xlsx");
      const ws = XLSX.utils.json_to_sheet(data);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, sheetName.slice(0, 31));
      const name = filename.endsWith(".xlsx") ? filename : `${filename}.xlsx`;
      XLSX.writeFile(wb, name);
    } catch (err) {
      console.error("Failed to export data to Excel:", err);
    } finally {
      setBusy(false);
    }
  };

  return (
    <Button
      type="button"
      variant="outline"
      size="sm"
      onClick={handleClick}
      disabled={disabled || busy || resolvedEmpty}
      className={className}
      data-testid={testId}
    >
      <Download className="h-3.5 w-3.5 mr-1.5" />
      {busy ? "Preparing\u2026" : label}
    </Button>
  );
}

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";

type CandidateResponse = {
  inputs?: {
    inventoryYear?: number;
    indicatorYear?: number;
    assumptions?: string[];
    readiness?: {
      status?: string;
      mainCase?: string;
      comparisonCase?: string;
      missing?: string[];
    };
    indicators?: {
      key?: string;
      label?: string;
      unit?: string;
      year?: number;
      value?: number | null;
      role?: string;
      reason?: string;
    }[];
  };
  result?: {
    validation?: string;
    temperature?: null;
    trajectory?: {
      year: number;
      reportingGtCO2e: number;
      nativeMt: Record<string, number>;
    }[];
  };
};

type ReviewScenario = "constant" | "transition" | "dashboard";
const scenarioLabels: Record<ReviewScenario, string> = {
  constant: "Constant-activity control",
  transition: "Illustrative transition",
  dashboard: "Dated dashboard-input diagnostic",
};

const reviewYears = [2024, 2030, 2050, 2100];
const formatEmissions = new Intl.NumberFormat("en", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

export function EmissionsCandidateReview() {
  const [scenario, setScenario] = useState<ReviewScenario>("constant");
  const { data, isLoading, isError, refetch, isFetching } = useQuery<CandidateResponse>({
    queryKey: [`/api/emissions/candidate?scenario=${scenario}`],
  });

  return (
    <section
      className="rounded-lg border bg-card text-card-foreground p-4 sm:p-6 space-y-4"
      aria-labelledby="emissions-candidate-heading"
      data-testid="emissions-candidate-review"
    >
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="space-y-1">
          <h2 id="emissions-candidate-heading" className="text-lg font-semibold">
            Package 2 · Emissions candidate review
          </h2>
          <p className="text-sm text-muted-foreground">
            Read-only candidate, not calibrated and not a forecast.
          </p>
        </div>
        <div className="space-y-1">
          <label htmlFor="emissions-candidate-scenario" className="block text-xs font-medium text-muted-foreground">
            Review scenario
          </label>
          <select
            id="emissions-candidate-scenario"
            className="rounded-md border border-input bg-background px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            value={scenario}
            onChange={(event) => setScenario(event.target.value as ReviewScenario)}
            data-testid="select-emissions-candidate-scenario"
          >
            <option value="constant">Constant-activity control</option>
            <option value="transition">Illustrative transition</option>
            <option value="dashboard">Dated dashboard-input diagnostic</option>
          </select>
        </div>
      </div>

      <p className="rounded-md border p-3 text-sm font-medium">
        Package 2 remains incomplete: the native-gas scenarios are not yet calibrated.
        The published CAT references above are independent comparisons, not outputs of this candidate model.
      </p>

      <p className="text-sm text-muted-foreground">
        This partial Package 2 review does not validate the legacy calculation and makes no new
        temperature claim. Calibration and source assessment are still pending.
      </p>

      {isLoading ? (
        <div role="status" aria-label="Loading candidate emissions" className="space-y-3">
          <span className="sr-only">Loading candidate emissions…</span>
          {reviewYears.map((year) => (
            <div key={year} className="h-8 rounded bg-muted animate-pulse" />
          ))}
        </div>
      ) : isError ? (
        <div role="alert" className="flex flex-wrap items-center justify-between gap-3 rounded-md border p-3">
          <p className="text-sm text-muted-foreground">
            Candidate emissions could not be loaded. No candidate values are shown.
          </p>
          <Button variant="outline" size="sm" onClick={() => void refetch()} disabled={isFetching}>
            {isFetching ? "Retrying…" : "Retry"}
          </Button>
        </div>
      ) : !data?.result?.trajectory?.length ? (
        <p className="rounded-md border p-3 text-sm text-muted-foreground">
          No candidate trajectory is available for this scenario.
        </p>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <caption className="text-left text-xs text-muted-foreground pb-2">
              {scenarioLabels[scenario]} · Reporting emissions only
            </caption>
            <thead>
              <tr className="border-b text-muted-foreground">
                <th scope="col" className="py-2 text-left font-medium">Year</th>
                <th scope="col" className="py-2 text-right font-medium">Emissions (GtCO2e)</th>
              </tr>
            </thead>
            <tbody>
              {reviewYears.map((year) => {
                const point = data?.result?.trajectory?.find((entry) => entry.year === year);
                return (
                  <tr key={year} className="border-b last:border-0">
                    <th scope="row" className="py-2 text-left font-normal tabular-nums">{year}</th>
                    <td className="py-2 text-right tabular-nums">
                      {point && Number.isFinite(point.reportingGtCO2e)
                        ? formatEmissions.format(point.reportingGtCO2e)
                        : "Not available"}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {!isLoading && !isError && data?.inputs && (
        <div className="space-y-4">
          <div className="space-y-2">
            <h3 className="text-sm font-semibold">Readiness and missing calibration</h3>
            <p className="text-xs text-muted-foreground">
              Inventory year: {data.inputs.inventoryYear ?? "Not available"} · Indicator year:{" "}
              {data.inputs.indicatorYear ?? "Not available"}
            </p>
            {data.inputs.readiness?.status && (
              <p className="text-sm text-muted-foreground">
                Reported readiness status: {data.inputs.readiness.status}
              </p>
            )}
            {data.inputs.readiness?.mainCase && (
              <p className="text-sm text-muted-foreground">
                Native-gas main-case basis (not yet calibrated): {data.inputs.readiness.mainCase}
              </p>
            )}
            {data.inputs.readiness?.comparisonCase && (
              <p className="text-sm text-muted-foreground">
                Native-gas comparison basis (not yet calibrated): {data.inputs.readiness.comparisonCase}
              </p>
            )}
            {data.inputs.readiness?.missing?.length ? (
              <ul aria-label="Missing readiness requirements" className="list-disc pl-5 space-y-1 text-sm text-muted-foreground">
                {data.inputs.readiness.missing.map((item, index) => (
                  <li key={index}>{item}</li>
                ))}
              </ul>
            ) : (
              <p className="text-sm text-muted-foreground">
                No missing-requirement details were supplied. This does not establish readiness.
              </p>
            )}
          </div>

          <details className="rounded-md border p-3">
            <summary className="cursor-pointer text-sm font-medium focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
              Indicator roles · 2024 values
            </summary>
            {data.inputs.indicators?.length ? (
              <div className="overflow-x-auto mt-3">
                <table className="w-full text-sm">
                  <caption className="text-left text-xs text-muted-foreground pb-2">
                    Dated input diagnostics, not calibrated policy cases. Values from other years
                    are identified rather than presented as 2024 observations.
                  </caption>
                  <thead>
                    <tr className="border-b text-muted-foreground">
                      <th scope="col" className="py-2 pr-4 text-left font-medium">Indicator</th>
                      <th scope="col" className="py-2 pr-4 text-left font-medium">2024 value / unit</th>
                      <th scope="col" className="py-2 pr-4 text-left font-medium">Role</th>
                      <th scope="col" className="py-2 text-left font-medium">Reason</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.inputs.indicators.map((indicator, index) => {
                      const year = indicator.year ?? data.inputs?.indicatorYear;
                      const value = typeof indicator.value === "number" && Number.isFinite(indicator.value)
                        ? formatEmissions.format(indicator.value)
                        : "Not available";
                      return (
                        <tr key={indicator.key ?? index} className="border-b last:border-0">
                          <th scope="row" className="py-2 pr-4 text-left font-normal">
                            {indicator.label ?? indicator.key ?? "Unnamed indicator"}
                          </th>
                          <td className="py-2 pr-4 tabular-nums">
                            {year === 2024 ? value : "2024 value not available"}
                            {year === 2024 && indicator.unit ? ` ${indicator.unit}` : ""}
                            {year !== 2024 && (
                              <span className="block text-xs text-muted-foreground">
                                {year ?? "Undated"} input: {value}{indicator.unit ? ` ${indicator.unit}` : ""}
                              </span>
                            )}
                          </td>
                          <td className="py-2 pr-4">{indicator.role ?? "Not supplied"}</td>
                          <td className="py-2">{indicator.reason ?? "Not supplied"}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            ) : (
              <p className="mt-3 text-sm text-muted-foreground">No indicator-role details are available.</p>
            )}
          </details>

          <div className="space-y-2">
            <h3 className="text-sm font-semibold">Diagnostic assumptions</h3>
            {data.inputs.assumptions?.length ? (
              <ul className="list-disc pl-5 space-y-1 text-sm text-muted-foreground">
                {data.inputs.assumptions.map((assumption, index) => (
                  <li key={index}>{assumption}</li>
                ))}
              </ul>
            ) : (
              <p className="text-sm text-muted-foreground">No assumptions were supplied.</p>
            )}
          </div>
        </div>
      )}

      <p className="text-xs text-muted-foreground">
        GtCO2e is a reporting aggregate, not a native species mass. Native species masses remain
        separate in Mt per species and are not combined in this table.
        {data?.result?.validation && !isError && (
          <span> Validation status: {data.result?.validation}. This is not calibration.</span>
        )}
      </p>
    </section>
  );
}

