              style: { fontSize: 10, fill: "hsl(var(--muted-foreground))" },
            }}
          />
        </AreaChart>
      </ResponsiveContainer>
    </Card>
  );
}

import { useQuery } from "@tanstack/react-query";
import type { FinancialProviderStatus as ProviderStatus } from "@shared/financialData";
