              </div>

              <div className="flex items-center gap-3 mt-1.5 text-xs text-muted-foreground">
                <span data-testid={`text-region-reduction-${region.region}`}>Reduction: {region.reductionRate.toFixed(1)}%/yr</span>
                <span data-testid={`text-region-intensity-${region.region}`}>Carbon Intensity: {region.carbonIntensity.toFixed(2)} kg/$</span>
                <span data-testid={`text-region-netzero-${region.region}`}>Net-Zero: {region.netZeroYear || "Never"}</span>
              </div>
            </div>
          );
        })}
      </div>
    </Card>
  );
}

import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceLine, Cell } from "recharts";
import type { SensitivityResult } from "@/lib/types";
import { DownloadDataButton } from "@/components/download-data-button";

interface SensitivityChartProps {
  data: SensitivityResult[];
  isLoading?: boolean;
}

function getCategoryColor(category: string): string {
  switch (category) {
    case "Technology": return "hsl(168, 76%, 36%)";
    case "Policy": return "hsl(43, 86%, 42%)";
    case "Corporate": return "hsl(27, 87%, 48%)";
    case "Socioeconomic": return "hsl(280, 65%, 50%)";
    case "Financial Flows": return "hsl(150, 65%, 40%)";
    case "Emissions Outcomes": return "hsl(0, 65%, 50%)";
    default: return "hsl(220, 65%, 50%)";
  }
}

function getCategoryBadgeClass(category: string): string {
  switch (category) {
    case "Technology": return "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400";
    case "Policy": return "bg-amber-500/10 text-amber-600 dark:text-amber-400";
    case "Corporate": return "bg-orange-500/10 text-orange-600 dark:text-orange-400";
    case "Socioeconomic": return "bg-purple-500/10 text-purple-600 dark:text-purple-400";
    case "Financial Flows": return "bg-teal-500/10 text-teal-600 dark:text-teal-400";
    case "Emissions Outcomes": return "bg-red-500/10 text-red-600 dark:text-red-400";
    default: return "bg-muted text-muted-foreground";
  }
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    payload: {
      label: string;
      category: string;
      low: number;
      high: number;
      range: number;
      baseline: number;
    };
  }>;
}

function CustomTooltip({ active, payload }: CustomTooltipProps) {
  if (!active || !payload?.[0]) return null;
  const d = payload[0].payload;
  return (
    <div className="bg-popover border rounded-md p-3 shadow-md text-sm">
      <p className="font-medium mb-1">{d.label}</p>
      <p className="text-muted-foreground text-xs mb-1">{d.category}</p>
      <div className="space-y-0.5 text-xs">
        <p>Baseline: <span className="font-medium tabular-nums">{d.baseline.toFixed(2)}</span>&deg;C</p>
        <p>Low scenario: <span className="font-medium tabular-nums text-blue-500">{d.low.toFixed(2)}</span>&deg;C</p>
        <p>High scenario: <span className="font-medium tabular-nums text-red-500">{d.high.toFixed(2)}</span>&deg;C</p>
        <p>Impact range: <span className="font-medium tabular-nums">{d.range.toFixed(3)}</span>&deg;C</p>
      </div>
    </div>
  );
}

export function SensitivityChart({ data, isLoading }: SensitivityChartProps) {
  if (isLoading) {
    return (
      <Card className="p-6">
        <Skeleton className="h-6 w-48 mb-4" />
        <Skeleton className="h-[400px] w-full" />
      </Card>
    );
  }

  if (!data?.length) return null;

  const baseline = data[0]?.baselineTemperature ?? 2.7;
  const top10 = data.slice(0, 10);

  const chartData = top10.map((d) => ({
    label: d.label,
    category: d.category,
    low: d.p10Temperature,
    high: d.p90Temperature,
    range: d.temperatureRange,
    baseline,
    lowOffset: d.p10Temperature - baseline,
    highOffset: d.p90Temperature - baseline,
  }));

  const minTemp = Math.min(...chartData.map(d => d.low)) - 0.05;
  const maxTemp = Math.max(...chartData.map(d => d.high)) + 0.05;

  const uniqueCategories = Array.from(new Set(top10.map(d => d.category)));

  const downloadRows = data.map((d) => ({
    Indicator: d.label,
    Category: d.category,
    "Baseline (\u00B0C)": d.baselineTemperature ?? baseline,
    "Low Scenario P10 (\u00B0C)": d.p10Temperature,
    "High Scenario P90 (\u00B0C)": d.p90Temperature,
    "Impact Range (\u00B0C)": d.temperatureRange,
  }));

  return (
    <Card className="p-6" data-testid="card-sensitivity-analysis">
      <div className="flex items-center justify-between mb-1 flex-wrap gap-3">
        <div>
          <h3 className="text-base font-semibold" data-testid="text-sensitivity-title">Indicator Sensitivity Analysis</h3>
          <p className="text-xs text-muted-foreground">Temperature impact when each indicator is varied between pessimistic and optimistic scenarios</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <div className="flex items-center gap-1.5 flex-wrap">
            {uniqueCategories.map(cat => (
              <Badge key={cat} variant="secondary" className={`text-[10px] px-1.5 py-0 ${getCategoryBadgeClass(cat)}`}>
                {cat}
              </Badge>
            ))}
          </div>
          <DownloadDataButton
            filename="indicator-sensitivity"
            sheetName="Sensitivity"
            rows={downloadRows}
            testId="button-download-sensitivity"
          />
        </div>
      </div>

      <div className="h-[380px] mt-4" data-testid="chart-sensitivity-tornado">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={chartData}
            layout="vertical"
            margin={{ top: 10, right: 20, left: 120, bottom: 20 }}
          >
            <XAxis
              type="number"
              domain={[minTemp, maxTemp]}
              tickFormatter={(v: number) => `${v.toFixed(1)}\u00B0C`}
              tick={{ fontSize: 10 }}
              label={{ value: "Temperature (\u00B0C)", position: "insideBottom", offset: -10, style: { fontSize: 10 } }}
            />
            <YAxis
              type="category"
              dataKey="label"
              tick={{ fontSize: 10 }}
              width={110}
            />
            <Tooltip content={<CustomTooltip />} />
            <ReferenceLine x={baseline} stroke="hsl(var(--muted-foreground))" strokeDasharray="3 3" strokeWidth={1.5} />
            <Bar dataKey="low" stackId="range" fill="transparent" isAnimationActive={false} />
            <Bar dataKey="range" stackId="range" isAnimationActive={false}>
              {chartData.map((entry, idx) => (
                <Cell key={idx} fill={getCategoryColor(entry.category)} fillOpacity={0.7} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>

      <div className="flex items-center justify-center gap-4 mt-2 text-xs text-muted-foreground">
        <div className="flex items-center gap-1.5">
          <div className="w-px h-4 border-l border-dashed border-muted-foreground" />
          <span>Baseline: {baseline.toFixed(2)}&deg;C</span>
        </div>
        <span>Wider bars indicate higher sensitivity to that indicator</span>
      </div>
    </Card>
  );
}

import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Thermometer, TrendingDown, Calendar } from "lucide-react";
import type { MetricView } from "@/lib/types";

interface TemperatureGaugeProps {
  temperature: number;
  p10: number;
  p90: number;
  reductionRate: number;
  netZeroYear: number | null;
  metricView: MetricView;
  isLoading?: boolean;
}

function getTemperatureColor(temp: number): string {
  if (temp <= 1.5) return "text-emerald-500";
  if (temp <= 2.0) return "text-sky-500";
  if (temp <= 2.5) return "text-amber-500";
  if (temp <= 3.0) return "text-orange-500";
  return "text-red-500";
}

function getTemperatureLabel(temp: number): { label: string; color: string; textColor: string } {
  if (temp <= 1.5) return { label: "Paris 1.5\u00B0C Goal", color: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400", textColor: "text-emerald-600 dark:text-emerald-400" };
  if (temp <= 2.0) return { label: "Paris 2\u00B0C Limit", color: "bg-sky-500/10 text-sky-600 dark:text-sky-400", textColor: "text-sky-600 dark:text-sky-400" };
  if (temp <= 2.5) return { label: "Moderate Warming", color: "bg-amber-500/10 text-amber-600 dark:text-amber-400", textColor: "text-amber-600 dark:text-amber-400" };
  if (temp <= 3.0) return { label: "High Warming", color: "bg-orange-500/10 text-orange-600 dark:text-orange-400", textColor: "text-orange-600 dark:text-orange-400" };
  return { label: "Dangerous Warming", color: "bg-red-500/10 text-red-600 dark:text-red-400", textColor: "text-red-600 dark:text-red-400" };
}

function getReductionColor(rate: number): string {
  if (rate >= 7.0) return "text-emerald-500";
  if (rate >= 5.0) return "text-sky-500";
  if (rate >= 3.0) return "text-amber-500";
  if (rate >= 1.0) return "text-orange-500";
  return "text-red-500";
}

function getReductionLabel(rate: number): { label: string; color: string; badgeColor: string } {
  if (rate >= 7.0) return { label: "Rapid Decarbonization", color: "text-emerald-600 dark:text-emerald-400", badgeColor: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400" };
  if (rate >= 5.0) return { label: "Strong Progress", color: "text-sky-600 dark:text-sky-400", badgeColor: "bg-sky-500/10 text-sky-600 dark:text-sky-400" };
  if (rate >= 3.0) return { label: "Moderate Progress", color: "text-amber-600 dark:text-amber-400", badgeColor: "bg-amber-500/10 text-amber-600 dark:text-amber-400" };
  if (rate >= 1.0) return { label: "Slow Progress", color: "text-orange-600 dark:text-orange-400", badgeColor: "bg-orange-500/10 text-orange-600 dark:text-orange-400" };
  return { label: "Insufficient Action", color: "text-red-600 dark:text-red-400", badgeColor: "bg-red-500/10 text-red-600 dark:text-red-400" };
}

function getNetZeroColor(year: number | null): string {
  if (!year) return "text-red-500";
  if (year <= 2050) return "text-emerald-500";
  if (year <= 2070) return "text-amber-500";
  if (year <= 2100) return "text-orange-500";
  return "text-red-500";
}

function getNetZeroLabel(year: number | null): { label: string; color: string } {
  if (!year) return { label: "Emissions remain high", color: "bg-red-500/10 text-red-600 dark:text-red-400" };
  if (year <= 2050) return { label: "On Track", color: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400" };
  if (year <= 2070) return { label: "Delayed", color: "bg-amber-500/10 text-amber-600 dark:text-amber-400" };
  if (year <= 2100) return { label: "Significantly Delayed", color: "bg-orange-500/10 text-orange-600 dark:text-orange-400" };
  return { label: "Beyond 2100", color: "bg-red-500/10 text-red-600 dark:text-red-400" };
}

export function TemperatureGauge({
  temperature,
  p10,
  p90,
  reductionRate,
  netZeroYear,
  metricView,
  isLoading,
}: TemperatureGaugeProps) {
  if (isLoading) {
    return (
      <Card className="p-6">
        <Skeleton className="h-8 w-48 mb-4" />
        <Skeleton className="h-24 w-full mb-4" />
        <Skeleton className="h-4 w-32" />
      </Card>
    );
  }

  const tempLabel = getTemperatureLabel(temperature);
  const reductionLabel = getReductionLabel(reductionRate);
  const netZeroLabel = getNetZeroLabel(netZeroYear);

  const gaugePercent = Math.min(100, Math.max(0, ((temperature - 1.0) / 4.0) * 100));
  const p10Percent = Math.min(100, Math.max(0, ((p10 - 1.0) / 4.0) * 100));
  const p90Percent = Math.min(100, Math.max(0, ((p90 - 1.0) / 4.0) * 100));

  if (metricView === "reductionRate") {
    return (
      <Card className="p-6" data-testid="card-temperature-gauge">
        <div className="flex items-center gap-2 mb-4">
          <TrendingDown className="h-5 w-5 text-muted-foreground" />
          <h3 className="text-sm font-medium text-muted-foreground">Emissions Reduction Rate</h3>
        </div>

        <div className="flex items-baseline gap-2 mb-1">
          <span className={`text-5xl font-bold tabular-nums tracking-tight ${getReductionColor(reductionRate)}`} data-testid="text-reduction-value">
            {reductionRate.toFixed(2)}
          </span>
          <span className="text-2xl font-medium text-muted-foreground">% / yr</span>
        </div>

        <div className={`inline-flex items-center px-2.5 py-0.5 rounded-md text-xs font-medium mb-4 ${reductionLabel.badgeColor}`} data-testid="text-reduction-label">
          {reductionLabel.label}
        </div>

        <div className="relative h-3 bg-muted rounded-full mb-2 overflow-hidden">
          <div
            className="absolute inset-y-0 left-0 rounded-full"
            style={{
              width: `${Math.min(100, (reductionRate / 10) * 100)}%`,
              background: `linear-gradient(90deg, hsl(0, 84%, 35%), hsl(43, 86%, 42%), hsl(168, 76%, 36%))`,
            }}
          />
        </div>

        <div className="flex justify-between text-xs text-muted-foreground mb-6">
          <span>0%</span>
          <span>5% (1.5°C aligned)</span>
          <span>10%+</span>
        </div>

        <div className="grid grid-cols-2 gap-4 pt-4 border-t">
          <div className="flex items-start gap-2">
            <Thermometer className="h-4 w-4 text-muted-foreground mt-0.5" />
            <div>
              <p className="text-xs text-muted-foreground">Temperature Rise</p>
              <p className={`text-sm font-semibold tabular-nums ${getTemperatureColor(temperature)}`} data-testid="text-temperature-value">
                {temperature.toFixed(2)}&deg;C
              </p>
              <p className={`text-xs ${tempLabel.textColor}`}>{tempLabel.label}</p>
            </div>
          </div>
          <div className="flex items-start gap-2">
            <Calendar className="h-4 w-4 text-muted-foreground mt-0.5" />
            <div>
              <p className="text-xs text-muted-foreground">Net-Zero Year</p>
              <p className="text-sm font-semibold tabular-nums" data-testid="text-net-zero-year">
                {netZeroYear ? netZeroYear : "Never"}
              </p>
              <p className="text-xs text-muted-foreground">
                {netZeroYear && netZeroYear <= 2050 ? "On track" : netZeroYear ? "Delayed" : "Emissions remain high"}
              </p>
            </div>
          </div>
        </div>
      </Card>
    );
  }

  if (metricView === "netZero") {
    return (
      <Card className="p-6" data-testid="card-temperature-gauge">
        <div className="flex items-center gap-2 mb-4">
          <Calendar className="h-5 w-5 text-muted-foreground" />
          <h3 className="text-sm font-medium text-muted-foreground">Projected Net-Zero Year</h3>
        </div>

        <div className="flex items-baseline gap-2 mb-1">
          <span className={`text-5xl font-bold tabular-nums tracking-tight ${getNetZeroColor(netZeroYear)}`} data-testid="text-netzero-value">
            {netZeroYear ? netZeroYear : "Never"}
          </span>
        </div>

        <div className={`inline-flex items-center px-2.5 py-0.5 rounded-md text-xs font-medium mb-4 ${netZeroLabel.color}`} data-testid="text-netzero-label">
          {netZeroLabel.label}
        </div>

        <div className="relative h-3 bg-muted rounded-full mb-2 overflow-hidden">
          {netZeroYear && (
            <div
              className="absolute inset-y-0 left-0 rounded-full"
              style={{
                width: `${Math.min(100, Math.max(0, ((2200 - netZeroYear) / (2200 - 2030)) * 100))}%`,
                background: `linear-gradient(90deg, hsl(168, 76%, 36%), hsl(43, 86%, 42%), hsl(0, 84%, 35%))`,
              }}
            />
          )}
        </div>

        <div className="flex justify-between text-xs text-muted-foreground mb-6">
          <span>2030</span>
          <span>2050 (target)</span>
          <span>2100+</span>
        </div>

        <div className="grid grid-cols-2 gap-4 pt-4 border-t">
          <div className="flex items-start gap-2">
            <Thermometer className="h-4 w-4 text-muted-foreground mt-0.5" />
            <div>
              <p className="text-xs text-muted-foreground">Temperature Rise</p>
              <p className={`text-sm font-semibold tabular-nums ${getTemperatureColor(temperature)}`} data-testid="text-temperature-value">
                {temperature.toFixed(2)}&deg;C
              </p>
              <p className={`text-xs ${tempLabel.textColor}`}>{tempLabel.label}</p>
            </div>
          </div>
          <div className="flex items-start gap-2">
            <TrendingDown className="h-4 w-4 text-muted-foreground mt-0.5" />
            <div>
              <p className="text-xs text-muted-foreground">Reduction Rate</p>
              <p className="text-sm font-semibold tabular-nums" data-testid="text-reduction-rate">
                {reductionRate.toFixed(2)}% / yr
              </p>
              <p className={`text-xs ${reductionLabel.color}`}>{reductionLabel.label}</p>
            </div>
          </div>
        </div>
      </Card>
    );
  }

  return (
    <Card className="p-6" data-testid="card-temperature-gauge">
      <div className="flex items-center gap-2 mb-4">
        <Thermometer className="h-5 w-5 text-muted-foreground" />
        <h3 className="text-sm font-medium text-muted-foreground">Implied Temperature Rise by 2100</h3>
      </div>

      <div className="flex items-baseline gap-2 mb-1">
        <span className={`text-5xl font-bold tabular-nums tracking-tight ${getTemperatureColor(temperature)}`} data-testid="text-temperature-value">
          {temperature.toFixed(2)}
        </span>
        <span className="text-2xl font-medium text-muted-foreground">&deg;C</span>
      </div>

      <div className={`inline-flex items-center px-2.5 py-0.5 rounded-md text-xs font-medium mb-4 ${tempLabel.color}`} data-testid="text-temperature-label">
        {tempLabel.label}
      </div>

      <div className="relative h-3 bg-muted rounded-full mb-2 overflow-hidden">
        <div
          className="absolute inset-y-0 left-0 rounded-full"
          style={{
            width: `${gaugePercent}%`,
            background: `linear-gradient(90deg, hsl(168, 76%, 36%), hsl(43, 86%, 42%), hsl(0, 84%, 35%))`,
          }}
        />
        <div
          className="absolute top-0 bottom-0 border-l-2 border-foreground/30"
          style={{ left: `${p10Percent}%` }}
        />
        <div
          className="absolute top-0 bottom-0 border-l-2 border-foreground/30"
          style={{ left: `${p90Percent}%` }}
        />
        <div
          className="absolute top-0 bottom-0 w-0.5 bg-foreground"
          style={{ left: `${12.5}%` }}
          title="1.5°C target"
        />
        <div
          className="absolute top-0 bottom-0 w-0.5 bg-foreground/50"
          style={{ left: `${25}%` }}
          title="2.0°C limit"
        />
      </div>

      <div className="flex justify-between text-xs text-muted-foreground mb-6">
        <span>1.0&deg;C</span>
        <span>P10: {p10.toFixed(1)}&deg;C</span>
        <span>P90: {p90.toFixed(1)}&deg;C</span>
        <span>5.0&deg;C</span>
      </div>

      <div className="grid grid-cols-2 gap-4 pt-4 border-t">
        <div className="flex items-start gap-2">
          <TrendingDown className="h-4 w-4 text-muted-foreground mt-0.5" />
          <div>
            <p className="text-xs text-muted-foreground">Reduction Rate</p>
            <p className="text-sm font-semibold tabular-nums" data-testid="text-reduction-rate">
              {reductionRate.toFixed(2)}% / yr
            </p>
            <p className={`text-xs ${reductionLabel.color}`}>{reductionLabel.label}</p>
          </div>
        </div>
        <div className="flex items-start gap-2">
          <Calendar className="h-4 w-4 text-muted-foreground mt-0.5" />
          <div>
            <p className="text-xs text-muted-foreground">Net-Zero Year</p>
            <p className="text-sm font-semibold tabular-nums" data-testid="text-net-zero-year">
              {netZeroYear ? netZeroYear : "Never"}
            </p>
            <p className="text-xs text-muted-foreground">
              {netZeroYear && netZeroYear <= 2050 ? "On track" : netZeroYear ? "Delayed" : "Emissions remain high"}
            </p>
          </div>
        </div>
      </div>
    </Card>
  );
}

import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  ReferenceLine,
  Cell,
} from "recharts";
import type { TemperatureProjection } from "@/lib/types";
import { DownloadDataButton } from "@/components/download-data-button";

interface TemperatureHistogramProps {
  pdf: TemperatureProjection[];
  median: number;
  p10: number;
  p90: number;
  isLoading?: boolean;
}

function getBarColor(temp: number): string {
  if (temp <= 1.5) return "hsl(168, 76%, 36%)";
  if (temp <= 2.0) return "hsl(197, 71%, 38%)";
  if (temp <= 2.5) return "hsl(43, 86%, 42%)";
  if (temp <= 3.0) return "hsl(27, 87%, 48%)";
  return "hsl(0, 84%, 35%)";
}

export function TemperatureHistogram({ pdf, median, p10, p90, isLoading }: TemperatureHistogramProps) {
  if (isLoading) {
    return (
      <Card className="p-6">
        <Skeleton className="h-6 w-48 mb-4" />
        <Skeleton className="h-[300px] w-full" />
      </Card>
    );
  }

  const filteredPdf = pdf.filter((d) => d.probability > 0.001);

  const downloadRows = pdf.map((d) => ({
    "Temperature (\u00B0C)": d.temperature,
    "Probability Density": d.probability,
  }));

  return (
    <Card className="p-6" data-testid="card-temperature-histogram">
      <div className="flex items-center justify-between mb-4 flex-wrap gap-2">
        <div>
          <h3 className="text-sm font-medium text-muted-foreground">Temperature Probability Distribution</h3>
          <p className="text-xs text-muted-foreground mt-0.5">10,000 Monte Carlo simulations</p>
        </div>
        <div className="flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-3 text-xs text-muted-foreground">
            <span>P10: {p10.toFixed(1)}&deg;C</span>
            <span className="font-semibold text-foreground">Median: {median.toFixed(2)}&deg;C</span>
            <span>P90: {p90.toFixed(1)}&deg;C</span>
          </div>
          <DownloadDataButton
            filename="temperature-distribution"
            sheetName="Temp Distribution"
            rows={downloadRows}
            testId="button-download-temperature"
          />
        </div>
      </div>

      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={filteredPdf} margin={{ top: 5, right: 10, left: 0, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} />
          <XAxis
            dataKey="temperature"
            stroke="hsl(var(--muted-foreground))"
            fontSize={11}
            tickLine={false}
            axisLine={false}
            tickFormatter={(v) => `${v}\u00B0C`}
          />
          <YAxis
            stroke="hsl(var(--muted-foreground))"
            fontSize={11}
