export default function ClimateValuation() {
  const [includeScope3, setIncludeScope3] = useState(false);
  const [winsorize, setWinsorize] = useState(true);
  const [costOfEquity, setCostOfEquity] = useState(8);
  const [decarbTercileMethod, setDecarbTercileMethod] = useState<"absolute" | "sector_relative" | "sub_sector_relative" | "industry_relative">("sector_relative");

  const { data: uploads } = useQuery<UploadRecord[]>({
    queryKey: ["/api/cv/uploads"],
    refetchInterval: 5000,
  });

  const { data: summary, isLoading: summaryLoading } = useQuery<Summary>({
    queryKey: ["/api/cv/summary"],
    refetchInterval: uploads?.some((u) => u.status === "processing") ? 5000 : false,
  });

  const latestCompletedUpload = uploads?.find((u) => u.status === "completed");
  const uploadId = latestCompletedUpload?.id;
  const hasTimeSeriesData = summary && summary.dateRange && Number(summary.dateRange.recordCount) > 0;

  const carbonPriceUrl = `/api/cv/carbon-price?uploadId=${uploadId}&method=sector_relative&includeScope3=${includeScope3}&winsorize=${winsorize}&inferenceMethod=carbon_intensity`;
  const { data: carbonPrices, isLoading: carbonPricesLoading } = useQuery<CarbonPricePoint[]>({
    queryKey: [carbonPriceUrl],
    enabled: !!uploadId && !!hasTimeSeriesData,
  });

  const costOfEquityDecimal = costOfEquity / 100;
  const sdgGrowthUrl = `/api/cv/sdg-growth?costOfEquity=${costOfEquityDecimal}`;
  const { data: sdgGrowth, isLoading: sdgGrowthLoading } = useQuery<SDGGrowthPoint[]>({
    queryKey: ["/api/cv/sdg-growth", costOfEquityDecimal],
    queryFn: async () => {
      const res = await fetch(sdgGrowthUrl, { credentials: "include" });
      if (!res.ok) throw new Error("Failed to fetch SDG growth data");
      return res.json();
    },
    enabled: !!hasTimeSeriesData,
  });

  const decarbTercileUrl = `/api/cv/decarb-terciles?method=${decarbTercileMethod}&costOfEquity=${costOfEquityDecimal}`;
  const { data: decarbTerciles, isLoading: decarbTercilesLoading } = useQuery<DecarbTercilePoint[]>({
    queryKey: ["/api/cv/decarb-terciles", decarbTercileMethod, costOfEquityDecimal],
    queryFn: async () => {
      const res = await fetch(decarbTercileUrl, { credentials: "include" });
      if (!res.ok) throw new Error("Failed to fetch decarb terciles");
      return res.json();
    },
    enabled: !!hasTimeSeriesData,
  });

  const formatChartDate = (timestamp: number) => {
    const d = new Date(timestamp);
    return d.toLocaleDateString("en-US", { month: "short", year: "2-digit" });
  };

  const formatTooltipDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
  };

  const carbonIntensityChartData = carbonPrices?.map((p) => ({
    date: new Date(p.date).getTime(),
    cleanPE: Math.round(p.bottomTercilePeRatio * 100) / 100,
    dirtyPE: Math.round(p.topTercilePeRatio * 100) / 100,
    cleanCount: p.bottomTercileCompanyCount,
    dirtyCount: p.topTercileCompanyCount,
  }));

  const sdgChartData = sdgGrowth?.map((p) => ({
    date: new Date(p.date).getTime(),
    cleanPE: Math.round(p.cleanPE * 100) / 100,
    dirtyPE: Math.round(p.dirtyPE * 100) / 100,
    cleanCount: p.cleanCount,
    dirtyCount: p.dirtyCount,
  }));

  const ambitionChartData = decarbTerciles?.map((p) => ({
    date: new Date(p.date).getTime(),
    bestPE: Math.round(p.bestTercilePE * 100) / 100,
    worstPE: Math.round(p.worstTercilePE * 100) / 100,
    bestCount: p.bestTercileCompanyCount,
    worstCount: p.worstTercileCompanyCount,
  }));

  const hasData = !!hasTimeSeriesData;

  return (
    <div className="bg-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        <QueryReadErrors prefix="/api/cv" />
        <div className="flex items-center justify-between flex-wrap gap-3">
          <div>
            <h1 className="text-xl font-bold tracking-tight" data-testid="text-cv-title">
              Company Valuation Research
            </h1>
            <p className="text-sm text-muted-foreground">
              Corporate Carbon Emissions vs. Market Valuations
            </p>
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            <input
              type="file"
              id="cv-file-upload"
              accept=".xlsx,.xls"
              className="hidden"
              disabled
              data-testid="input-file-upload"
            />
            <Button
              variant="default"
              disabled
              title={OPERATOR_ONLY_REASON}
              data-testid="button-upload"
            >
              <Upload className="h-4 w-4" />
              <span className="ml-2">Upload Excel Data</span>
            </Button>
          </div>
        </div>
        <OperatorOnlyNotice />

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <SummaryCard icon={Building2} label="Companies" value={summary?.companiesCount ?? null} isLoading={summaryLoading} />
          <SummaryCard icon={FileSpreadsheet} label="Records" value={summary?.dateRange?.recordCount ?? null} isLoading={summaryLoading} />
          <SummaryCard icon={Factory} label="Sectors" value={summary?.sectors ?? null} isLoading={summaryLoading} />
          <SummaryCard icon={TrendingUp} label="Geographies" value={summary?.geographies ?? null} isLoading={summaryLoading} />
        </div>

        {summary?.imputation && summary.imputation.imputedRecords > 0 && (
          <div
            className="flex items-start gap-2 rounded-md border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-700 dark:text-amber-400"
            data-testid="text-imputation-disclosure"
          >
            <Info className="h-3.5 w-3.5 mt-0.5 shrink-0" />
            <span>
              {summary.imputation.imputedRecords.toLocaleString()} of{" "}
              {summary.imputation.totalRecords.toLocaleString()} records (
              {(summary.imputation.imputedFraction * 100).toFixed(1)}%) use carried-forward
              (imputed) emissions where a reporting gap exists. Carbon-intensity and pricing
              for these periods rely on the most recent observed scope 1/2/3 values.
            </span>
          </div>
        )}

        {uploads && uploads.length > 0 && (
          <Card className="p-4">
            <h3 className="text-sm font-medium mb-3" data-testid="text-uploads-heading">Recent Uploads</h3>
            <div className="space-y-2">
              {uploads.slice(0, 3).map((u) => (
                <div key={u.id} className="flex items-center justify-between gap-2 text-sm flex-wrap" data-testid={`row-upload-${u.id}`}>
                  <div className="flex items-center gap-2">
                    <FileSpreadsheet className="h-4 w-4 text-muted-foreground" />
                    <span className="truncate max-w-[200px]">{u.filename}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge
                      variant={u.status === "completed" ? "default" : u.status === "processing" ? "secondary" : "destructive"}
                      data-testid={`badge-upload-status-${u.id}`}
                    >
                      {u.status === "processing" && <RefreshCw className="h-3 w-3 animate-spin mr-1" />}
                      {u.status}
                    </Badge>
                    {u.status === "completed" && u.companiesCount && (
                      <span className="text-muted-foreground text-xs">{u.companiesCount} companies</span>
                    )}
                    {(u.status === "processing" || u.status === "failed") && (
                      <Button size="sm" variant="outline" data-testid={`button-reset-upload-${u.id}`} disabled title={OPERATOR_ONLY_REASON}>
                        {u.status === "processing" ? "Recover" : "Retry"}
                      </Button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </Card>
        )}

        {hasData && (
          <Card className="p-4">
            <h3 className="text-sm font-medium mb-3" data-testid="text-config-heading">Analysis Configuration</h3>
            <div className="flex flex-wrap items-center gap-4">
              <div className="flex items-center gap-2">
                <Label className="text-sm text-muted-foreground whitespace-nowrap">Cost of Equity</Label>
                <div className="flex items-center gap-1">
                  <input
                    type="number"
                    min="1"
                    max="30"
                    step="0.5"
                    defaultValue={costOfEquity}
                    onBlur={(e) => {
                      const val = parseFloat(e.target.value);
                      if (!isNaN(val) && val > 0 && val <= 30) setCostOfEquity(val);
                      else e.target.value = String(costOfEquity);
                    }}
                    onKeyDown={(e) => { if (e.key === "Enter") (e.target as HTMLInputElement).blur(); }}
                    className="w-16 h-9 rounded-md border bg-background px-2 text-sm text-center"
                    data-testid="input-cost-of-equity"
                  />
                  <span className="text-sm text-muted-foreground">%</span>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Switch id="scope3-switch" checked={includeScope3} onCheckedChange={setIncludeScope3} data-testid="switch-scope3" />
                <Label htmlFor="scope3-switch" className="text-sm text-muted-foreground whitespace-nowrap">Include Scope 3</Label>
              </div>
              <div className="flex items-center gap-2">
                <Switch id="winsorize-switch" checked={winsorize} onCheckedChange={setWinsorize} data-testid="switch-winsorize" />
                <Label htmlFor="winsorize-switch" className="text-sm text-muted-foreground whitespace-nowrap">Winsorize (5%)</Label>
              </div>
            </div>
          </Card>
        )}

        {hasData ? (
          <div className="space-y-10">

            <AnalysisSection
              icon={Factory}
              title="High vs Low Carbon Companies"
              description={`Companies ranked by emissions per market cap, not revenue, into terciles. P/E differences are descriptive valuation diagnostics. Gordon steady-state baseline g = ${costOfEquity}% − 1/PE assumes earnings are fully distributable; it is not a decarbonization rate or five-year reverse-DCF growth.`}
              chartData={carbonIntensityChartData ?? []}
              isLoading={carbonPricesLoading}
              formatChartDate={formatChartDate}
              formatTooltipDate={formatTooltipDate}
              testIdPrefix="carbon"
              peChart={{
                highKey: "cleanPE",
                lowKey: "dirtyPE",
                highLabel: "Low Carbon (Clean)",
                lowLabel: "High Carbon (Dirty)",
                tooltip: (d) => (
                  <div className="bg-card border rounded-md p-3 text-xs space-y-1.5 shadow-md" style={{ minWidth: 200 }}>
                    <div className="font-medium">{formatTooltipDate(d.date)}</div>
                    <div className="space-y-0.5">
                      <div><span className="inline-block w-2 h-2 rounded-full mr-1.5" style={{ backgroundColor: "hsl(168, 76%, 36%)" }} />Low Carbon P/E: <span className="font-semibold">{d.cleanPE?.toFixed(1)}x</span> ({d.cleanCount} co.)</div>
                      <div><span className="inline-block w-2 h-2 rounded-full mr-1.5" style={{ backgroundColor: "hsl(0, 72%, 51%)" }} />High Carbon P/E: <span className="font-semibold">{d.dirtyPE?.toFixed(1)}x</span> ({d.dirtyCount} co.)</div>
                    </div>
                  </div>
                ),
              }}
            />

            <AnalysisSection
              icon={Leaf}
              title="High vs Low SDG-Aligned Companies"
              description={`Companies grouped by SDG alignment. Gordon steady-state earnings-growth baselines at ${costOfEquity}% cost of equity are not identified market climate expectations or measured emissions reductions.`}
              chartData={sdgChartData ?? []}
              isLoading={sdgGrowthLoading}
              formatChartDate={formatChartDate}
              formatTooltipDate={formatTooltipDate}
              testIdPrefix="sdg"
              peChart={{
                highKey: "cleanPE",
                lowKey: "dirtyPE",
                highLabel: "Positive SDG (Clean)",
                lowLabel: "Negative SDG (Dirty)",
                tooltip: (d) => (
                  <div className="bg-card border rounded-md p-3 text-xs space-y-1.5 shadow-md" style={{ minWidth: 200 }}>
                    <div className="font-medium">{formatTooltipDate(d.date)}</div>
                    <div className="space-y-0.5">
                      <div><span className="inline-block w-2 h-2 rounded-full mr-1.5" style={{ backgroundColor: "hsl(168, 76%, 36%)" }} />Positive SDG P/E: <span className="font-semibold">{d.cleanPE?.toFixed(1)}x</span> ({d.cleanCount} co.)</div>
                      <div><span className="inline-block w-2 h-2 rounded-full mr-1.5" style={{ backgroundColor: "hsl(0, 72%, 51%)" }} />Negative SDG P/E: <span className="font-semibold">{d.dirtyPE?.toFixed(1)}x</span> ({d.dirtyCount} co.)</div>
                    </div>
                  </div>
                ),
              }}
            />

            <AnalysisSection
              icon={Target}
              title="High vs Low Ambition Companies"
              description={`Companies grouped by announced targets. P/E differences do not establish emissions outcomes. Gordon steady-state baselines use ${costOfEquity}% cost of equity, not a validated valuation-to-activity mapping.`}
              chartData={ambitionChartData ?? []}
              isLoading={decarbTercilesLoading}
              formatChartDate={formatChartDate}
              formatTooltipDate={formatTooltipDate}
              testIdPrefix="ambition"
              headerRight={
                <Select value={decarbTercileMethod} onValueChange={(v: "absolute" | "sector_relative" | "sub_sector_relative" | "industry_relative") => setDecarbTercileMethod(v)}>
                  <SelectTrigger className="w-[180px]" data-testid="select-decarb-tercile-method">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="absolute">Absolute</SelectItem>
                    <SelectItem value="sector_relative">Sector Relative</SelectItem>
                    <SelectItem value="sub_sector_relative">Sub-Sector Relative</SelectItem>
                    <SelectItem value="industry_relative">Industry Relative</SelectItem>
                  </SelectContent>
                </Select>
              }
              peChart={{
                highKey: "bestPE",
                lowKey: "worstPE",
                highLabel: "Most Ambitious",
                lowLabel: "Least Ambitious",
                tooltip: (d) => (
                  <div className="bg-card border rounded-md p-3 text-xs space-y-1.5 shadow-md" style={{ minWidth: 200 }}>
                    <div className="font-medium">{formatTooltipDate(d.date)}</div>
                    <div className="space-y-0.5">
                      <div><span className="inline-block w-2 h-2 rounded-full mr-1.5" style={{ backgroundColor: "hsl(168, 76%, 36%)" }} />Most Ambitious P/E: <span className="font-semibold">{d.bestPE?.toFixed(1)}x</span> ({d.bestCount} co.)</div>
                      <div><span className="inline-block w-2 h-2 rounded-full mr-1.5" style={{ backgroundColor: "hsl(0, 72%, 51%)" }} />Least Ambitious P/E: <span className="font-semibold">{d.worstPE?.toFixed(1)}x</span> ({d.worstCount} co.)</div>
                    </div>
                  </div>
                ),
              }}
            />

          </div>
        ) : (
          <Card className="p-12">
            <div className="text-center space-y-4">
              <div className="flex items-center justify-center w-16 h-16 rounded-md bg-primary/10 mx-auto">
                <DollarSign className="h-8 w-8 text-primary" />
              </div>
              <div>
                <h3 className="text-lg font-medium" data-testid="text-no-data-heading">No company dataset available</h3>
                <p className="text-sm text-muted-foreground mt-1 max-w-md mx-auto">
                  An operator must import and review company data using the CLI.
                  Valuation-derived temperature, carbon-price and net-zero outputs remain withheld.
                </p>
              </div>
              <Button variant="default" disabled title={OPERATOR_ONLY_REASON} data-testid="button-upload-cta">
                <Upload className="h-4 w-4 mr-2" />
                Upload Excel File
              </Button>
            </div>
          </Card>
        )}
      </div>
    </div>
  );
}

interface AnalysisSectionProps {
  icon: React.ElementType;
  title: string;
  description: string;
  chartData: Array<{ date: number; [k: string]: any }>;
  isLoading: boolean;
  formatChartDate: (ts: number) => string;
  formatTooltipDate: (ts: number) => string;
  testIdPrefix: string;
  headerRight?: React.ReactNode;
  peChart: {
    highKey: string;
    lowKey: string;
    highLabel: string;
    lowLabel: string;
    tooltip: (d: any) => React.ReactNode;
  };
}

function AnalysisSection({
  icon: Icon,
  title,
  description,
  chartData,
  isLoading,
  formatChartDate,
  formatTooltipDate,
  testIdPrefix,
  headerRight,
  peChart,
}: AnalysisSectionProps) {
  const peDownloadRows = chartData.map((d) => ({
    Date: formatTooltipDate(d.date),
    [`${peChart.highLabel} P/E (x)`]: d[peChart.highKey],
    [`${peChart.lowLabel} P/E (x)`]: d[peChart.lowKey],
  }));

  return (
    <section>
      <div className="flex items-center justify-between flex-wrap gap-3 mb-2">
        <h2 className="text-lg font-semibold flex items-center gap-2" data-testid={`text-${testIdPrefix}-heading`}>
          <Icon className="h-5 w-5 text-muted-foreground" />
          {title}
        </h2>
        {headerRight}
      </div>
      <p className="text-sm text-muted-foreground mb-4">{description}</p>

      <Card className="p-4 mb-6 text-sm text-muted-foreground" data-testid={`${testIdPrefix}-withheld`}>
        Temperature, carbon price, net-zero year and physical decarbonization rates: unavailable.
        No defensible valuation-to-activity mapping has been established. No numeric substitutes are shown or exported.
      </Card>

      <div className="space-y-6">
        <Card className="p-6">
          <div className="flex items-center justify-between gap-3 mb-4 flex-wrap">
            <div>
              <h3 className="text-sm font-medium" data-testid={`text-${testIdPrefix}-pe-chart-heading`}>P/E Ratio Comparison</h3>
              <p className="text-xs text-muted-foreground mt-1">{peChart.highLabel} vs {peChart.lowLabel} over time</p>
            </div>
            <DownloadDataButton
              filename={`${testIdPrefix}-pe-ratio-comparison`}
              sheetName="P-E Ratio"
              rows={peDownloadRows}
              testId={`button-download-${testIdPrefix}-pe`}
            />
          </div>
          {isLoading ? (
            <Skeleton className="h-[300px] w-full" />
          ) : chartData.length > 0 ? (
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" className="opacity-30" />
                <XAxis dataKey="date" type="number" domain={["dataMin", "dataMax"]} scale="time" tick={{ fontSize: 11 }} tickFormatter={formatChartDate} className="text-muted-foreground" />
                <YAxis tick={{ fontSize: 11 }} tickFormatter={(v: number) => `${v.toFixed(0)}x`} className="text-muted-foreground" />
                <Tooltip content={({ active, payload }) => {
                  if (!active || !payload || payload.length === 0) return null;
                  return <>{peChart.tooltip(payload[0].payload)}</>;
                }} />
                <Legend verticalAlign="top" height={30} iconType="line" wrapperStyle={{ fontSize: 11 }} />
                <Line type="monotone" dataKey={peChart.highKey} stroke="hsl(168, 76%, 36%)" strokeWidth={2} dot={false} activeDot={{ r: 4 }} name={peChart.highLabel} />
                <Line type="monotone" dataKey={peChart.lowKey} stroke="hsl(0, 72%, 51%)" strokeWidth={2} dot={false} activeDot={{ r: 4 }} name={peChart.lowLabel} />
              </LineChart>
            </ResponsiveContainer>
          ) : (
            <div className="flex items-center justify-center h-[300px] text-sm text-muted-foreground">No data available</div>
          )}
        </Card>

      </div>
    </section>
  );
}

function SummaryCard({ icon: Icon, label, value, isLoading }: { icon: React.ElementType; label: string; value: number | null; isLoading?: boolean }) {
  if (isLoading) {
    return (
      <Card className="p-4">
        <Skeleton className="h-4 w-20 mb-2" />
        <Skeleton className="h-7 w-16" />
      </Card>
    );
  }
  return (
    <Card className="p-4" data-testid={`card-summary-${label.toLowerCase()}`}>
      <div className="flex items-center gap-2 mb-1">
        <Icon className="h-4 w-4 text-muted-foreground" />
        <span className="text-xs text-muted-foreground">{label}</span>
      </div>
      <p className="text-xl font-semibold">{value?.toLocaleString() ?? "Unavailable"}</p>
    </Card>
  );
}

import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { TemperatureGauge } from "@/components/temperature-gauge";
import { EmissionsChart } from "@/components/emissions-chart";
import { EmissionsCandidateReview } from "@/components/emissions-candidate-review";
import { PublishedScenarioReferences } from "@/components/published-scenario-references";
import { TemperatureHistogram } from "@/components/temperature-histogram";
import { IndicatorCards } from "@/components/indicator-cards";
import { CategoryFilter } from "@/components/category-filter";
import { HistoricalTrendChart } from "@/components/historical-trend-chart";
import { RegionalComparison } from "@/components/regional-comparison";
import { MetricToggle } from "@/components/metric-toggle";
import { CategoryComparison } from "@/components/category-comparison";
import { SensitivityChart } from "@/components/sensitivity-chart";
import { CategoryTrendChart } from "@/components/category-trend-chart";
import { Button } from "@/components/ui/button";
import { RefreshCw } from "lucide-react";
import { queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import type {
  Category,
  MetricView,
  ProjectionResult,
  HistoricalIndicatorData,
  HistoricalTrendPoint,
  CategoryProjectionResult,
  CategoryHistoricalTrendPoint,
  RegionalProjection,
  SensitivityResult,
} from "@/lib/types";

export default function Dashboard() {
  const [showLegacy, setShowLegacy] = useState(false);
  const { toast } = useToast();
  const reload = useMutation({
    mutationFn: () => queryClient.invalidateQueries({ refetchType: "active" }, { throwOnError: true }),
    onSuccess: () => toast({ title: "Views reloaded", description: "Existing server results were read again. No data collection, server recalculation or model promotion was requested." }),
    onError: () => toast({ title: "Reload failed", description: "Some existing results could not be read. Retry when the service is available.", variant: "destructive" }),
  });
  const { data: indicators, isLoading, isError, refetch } = useQuery<HistoricalIndicatorData[]>({
    queryKey: ["/api/indicators/historical"],
  });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-xl font-bold tracking-tight" data-testid="text-title">Global Decarbonization Dashboard</h1>
          <p className="text-sm text-muted-foreground">Climate evidence and published scenario references</p>
        </div>
        <Button variant="outline" size="sm" onClick={() => reload.mutate()} disabled={reload.isPending} data-testid="button-refresh-analysis">
          <RefreshCw className="h-4 w-4 mr-1.5" />
          {reload.isPending ? "Reloading views…" : "Re-run Analysis"}
        </Button>
      </div>
      <p className="text-sm text-muted-foreground">
        Re-run Analysis reloads client queries only. It does not collect data or recalculate server results.
        No new scientific model is ready for use; legacy calculations are not validated climate forecasts.
      </p>
      <PublishedScenarioReferences />
      <EmissionsCandidateReview />
      <section className="space-y-4">
        <h2 className="text-lg font-semibold">Indicator evidence</h2>
        <p className="text-sm text-muted-foreground">Review source provenance and distinguish observations, curated values and estimates before interpreting these indicators.</p>
        {isError ? <div role="alert" className="rounded-md border p-4">Indicator evidence could not be loaded. <Button variant="outline" onClick={() => void refetch()}>Retry</Button></div>
          : !isLoading && !indicators?.length ? <p className="rounded-md border p-4 text-sm text-muted-foreground">No indicator evidence is available. No values have been substituted.</p>
          : <IndicatorCards historicalData={indicators ?? []} isLoading={isLoading} />}
      </section>
      <section className="rounded-md border p-4 space-y-3">
        <h2 className="text-lg font-semibold">Legacy diagnostic view — opt in</h2>
        <p className="text-sm text-muted-foreground" id="legacy-warning">
          The legacy calculation applies a CO2-only response to aggregate GHG (CO2e), plus a fixed 1.1°C offset.
          Its temperature, net-zero, regional and sensitivity outputs are unsupported diagnostics, not validated physical forecasts.
          The legacy milestone uses a fixed 5 Gt threshold and may extrapolate beyond 2100; it is not a 5% of 2024 milestone.
          Regional temperatures are not standalone regional warming estimates. Historical recalculations are not forecast validation.
        </p>
        <Button variant="outline" aria-expanded={showLegacy} aria-describedby="legacy-warning" onClick={() => setShowLegacy(!showLegacy)} data-testid="button-toggle-legacy">
          {showLegacy ? "Hide legacy diagnostics" : "Show legacy diagnostics"}
        </Button>
        {showLegacy && <LegacyDashboard />}
      </section>
    </div>
  );
}

function LegacyDashboard() {
  const [activeCategory, setActiveCategory] = useState<Category>("all");
  const [metricView, setMetricView] = useState<MetricView>("temperature");

  const projectionUrl = activeCategory === "all"
    ? "/api/projection"
    : `/api/projection?category=${activeCategory}`;

  const { data: projection, isLoading: projectionLoading } = useQuery<ProjectionResult>({
    queryKey: [projectionUrl],
  });

  const { data: historicalIndicators, isLoading: indicatorsLoading } = useQuery<HistoricalIndicatorData[]>({
    queryKey: ["/api/indicators/historical"],
  });

  const { data: historicalTrend, isLoading: trendLoading } = useQuery<HistoricalTrendPoint[]>({
    queryKey: ["/api/projection/historical-trend"],
  });

  const { data: categoryProjections, isLoading: categoriesLoading } = useQuery<CategoryProjectionResult[]>({
    queryKey: ["/api/projection/categories"],
  });

  const { data: regionalProjections, isLoading: regionsLoading } = useQuery<RegionalProjection[]>({
    queryKey: ["/api/projection/regions"],
  });

  const { data: sensitivityData, isLoading: sensitivityLoading } = useQuery<SensitivityResult[]>({
    queryKey: ["/api/projection/sensitivity"],
  });

  const { data: categoryHistoricalTrend, isLoading: categoryTrendLoading } = useQuery<CategoryHistoricalTrendPoint[]>({
    queryKey: ["/api/projection/categories/historical-trend"],
  });

  return (
    <div className="bg-background">
