interface IndicatorSummary {
  key: string;
  label: string;
  unit: string;
  category: string;
  source: string;
  tier: string;
  fetchMethod: string;
  decimals: number;
  appliedYear: number;
  appliedValue: number;
  appliedIsNowcast?: boolean;
  provenance: string;
  provenanceSource: string;
  provenanceAsOf?: string | null;
  curatedLatest: number | null;
  pendingCount: number;
}

interface IndicatorsResponse {
  indicators: IndicatorSummary[];
  baselineYear: number;
  latestYear: number;
}

interface Proposal {
  id: string;
  indicatorKey: string;
  year: number;
  value: number;
  source: string;
  sourceUrl: string | null;
  asOfDate: string | null;
  method: string;
  status: string;
  note: string | null;
  createdAt: string;
  decidedAt: string | null;
}

interface SeriesPoint {
  year: number;
  value: number;
  source: string;
  method: string;
  asOfDate?: string | null;
  sourceUrl?: string | null;
  overridden: boolean;
  isNowcast?: boolean;
}

interface IndicatorDetail {
  def: IndicatorSummary;
  series: SeriesPoint[];
  proposals: Proposal[];
}

interface FetchRun {
  id: string;
  trigger: string;
  status: string;
  startedAt: string;
  finishedAt: string | null;
  proposalsCreated: number;
  adaptersSucceeded: number;
  adaptersFailed: number;
}

interface RunsResponse {
  runs: FetchRun[];
}

const CATEGORY_ORDER = [
  "Technology",
  "Policy",
  "Corporate",
  "Socioeconomic",
  "Financial Flows",
  "Emissions Outcomes",
];

function formatValue(value: number | null | undefined, decimals: number): string {
  if (value === null || value === undefined || Number.isNaN(value)) return "—";
  return value.toLocaleString(undefined, {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

function provenanceBadge(provenance: string) {
  if (provenance === "curated") {
    return (
      <Badge variant="secondary" data-testid="badge-provenance-curated">
        Curated
      </Badge>
    );
  }
  if (provenance === "manual") {
    return <Badge data-testid="badge-provenance-manual">Manual</Badge>;
  }
  if (provenance === "nowcast") {
    return (
      <Badge variant="outline" className="border-muted-foreground text-muted-foreground" data-testid="badge-provenance-nowcast">
        Nowcast (estimated)
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="border-primary text-primary" data-testid="badge-provenance-estimated">
      Estimated ({provenance})
    </Badge>
  );
}

function formatDateTime(iso: string | null): string {
  if (!iso) return "—";
  const d = new Date(iso);
  return d.toLocaleString();
}

