function IndicatorDetailDialog({
  indicatorKey,
  onClose,
}: {
  indicatorKey: string | null;
  onClose: () => void;
}) {
  const [manualYear, setManualYear] = useState("");
  const [manualValue, setManualValue] = useState("");
  const [manualNote, setManualNote] = useState("");

  const { data: detail, isLoading, isError } = useQuery<IndicatorDetail>({
    queryKey: ["/api/data/indicator", indicatorKey],
    enabled: !!indicatorKey,
  });

  const pending = (detail?.proposals ?? []).filter((p) => p.status === "pending");
  const decided = (detail?.proposals ?? []).filter(
    (p) => p.status === "approved" || p.status === "rejected",
  );
  const def = detail?.def;

  const series = detail?.series ?? [];
  const firstNowcastIdx = series.findIndex((p) => p.isNowcast);
  const chartData = series.map((p, i) => ({
    year: p.year,
    actual: p.isNowcast ? null : p.value,
    estimated:
      p.isNowcast || (firstNowcastIdx > 0 && i === firstNowcastIdx - 1)
        ? p.value
        : null,
    source: p.source,
    isNowcast: !!p.isNowcast,
  }));
  const hasEstimated = firstNowcastIdx !== -1;

  const downloadRows = series.map((p) => ({
    Year: p.year,
    [`Value (${def?.unit ?? ""})`]: p.value,
    Type: p.isNowcast ? "Estimated (nowcast)" : "Sourced (observed)",
    Source: p.source,
    Method: p.method,
    "As Of Date": p.asOfDate ?? "",
  }));

  return (
    <Dialog open={!!indicatorKey} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto" data-testid="dialog-indicator-detail">
        <QueryReadErrors prefix="/api/data/indicator" />
        {isError ? <p className="text-sm text-muted-foreground">Indicator details are unavailable. Retry the read above or close this dialog.</p> : isLoading || !detail ? (
          <div className="space-y-3">
            <Skeleton className="h-6 w-1/2" />
            <Skeleton className="h-48 w-full" />
          </div>
        ) : (
          <>
            <DialogHeader>
              <DialogTitle data-testid="text-detail-title">
                {def?.label} <span className="text-muted-foreground font-normal">({def?.unit})</span>
              </DialogTitle>
              <DialogDescription>
                {def?.source} · {def?.category} · fetch method: {def?.fetchMethod}
              </DialogDescription>
            </DialogHeader>
            <OperatorOnlyNotice />

            <div className="flex items-center justify-between gap-2 flex-wrap">
              <h3 className="text-sm font-semibold">Time series</h3>
              <DownloadDataButton
                filename={`indicator-time-series-${def?.key ?? "series"}`}
                sheetName="Time Series"
                rows={downloadRows}
                testId="button-download-timeseries"
              />
            </div>

            <div className="h-56 w-full" data-testid="chart-timeseries">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData} margin={{ top: 8, right: 12, bottom: 4, left: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} width={56} domain={["auto", "auto"]} />
                  <RechartsTooltip
                    content={({ active, payload, label }) => {
                      if (!active || !payload || payload.length === 0) return null;
                      const entry =
                        payload.find((p) => p.value != null) ?? payload[0];
                      const pt = entry.payload as (typeof chartData)[number];
                      return (
                        <div className="rounded-md border bg-background p-2 text-xs shadow-sm">
                          <p className="font-semibold">
                            {label}: {formatValue(pt.actual ?? pt.estimated ?? 0, def?.decimals ?? 2)}{" "}
                            {def?.unit}
                          </p>
                          <p className="text-muted-foreground">
                            {pt.isNowcast ? "Estimated — " : "Sourced — "}
                            {pt.source}
                          </p>
                        </div>
                      );
                    }}
                  />
                  <Legend
                    verticalAlign="top"
                    height={24}
                    iconType="plainline"
                    wrapperStyle={{ fontSize: 11 }}
                  />
                  <Line
                    type="monotone"
                    dataKey="actual"
                    name="Sourced (observed)"
                    stroke="hsl(var(--primary))"
                    strokeWidth={2}
                    dot={{ r: 3 }}
                    connectNulls={false}
                  />
                  {hasEstimated && (
                    <Line
                      type="monotone"
                      dataKey="estimated"
                      name="Estimated (nowcast)"
                      stroke="hsl(var(--primary))"
                      strokeWidth={2}
                      strokeDasharray="5 4"
                      dot={(props: any) => {
                        const { cx, cy, payload, key } = props;
                        if (!payload?.isNowcast || cx == null || cy == null) {
                          return <g key={key} />;
                        }
                        return (
                          <circle
                            key={key}
                            cx={cx}
                            cy={cy}
                            r={3}
                            fill="hsl(var(--background))"
                            stroke="hsl(var(--primary))"
                            strokeWidth={2}
                          />
                        );
                      }}
                      connectNulls
                    />
                  )}
                </LineChart>
              </ResponsiveContainer>
            </div>

            {pending.length > 0 && (
              <>
                <Separator />
                <div className="space-y-2">
                  <h3 className="text-sm font-semibold">Pending proposals</h3>
                  {pending.map((p) => (
                    <div
                      key={p.id}
                      className="flex items-center justify-between gap-3 rounded-md border p-3"
                      data-testid={`proposal-${p.id}`}
                    >
                      <div className="min-w-0 text-sm">
                        <p className="font-mono font-semibold">
                          {p.year}: {formatValue(p.value, def?.decimals ?? 2)} {def?.unit}
                        </p>
                        <p className="text-xs text-muted-foreground flex items-center gap-1">
                          {p.source}
                          {p.sourceUrl && (
                            <a
                              href={p.sourceUrl}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center text-primary hover:underline"
                              data-testid={`link-source-${p.id}`}
                              onClick={(e) => e.stopPropagation()}
                            >
                              <ExternalLink className="h-3 w-3" />
                            </a>
                          )}
                          {p.asOfDate ? ` · as of ${p.asOfDate}` : ""}
                        </p>
                      </div>
                      <div className="flex items-center gap-2 shrink-0">
                        <Button
                          size="sm"
                          disabled
                          title={OPERATOR_ONLY_REASON}
                          data-testid={`button-approve-${p.id}`}
                        >
                          <Check className="h-4 w-4" /> Approve
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          disabled
                          title={OPERATOR_ONLY_REASON}
                          data-testid={`button-reject-${p.id}`}
                        >
                          <X className="h-4 w-4" /> Reject
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}

            <Separator />
            <fieldset disabled className="space-y-2">
              <h3 className="text-sm font-semibold">Manual entry / edit</h3>
              <p className="text-xs text-muted-foreground">
                Manual entry is unavailable in the dashboard. An operator must review and apply changes using the CLI.
              </p>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                <div>
                  <Label htmlFor="manual-year" className="text-xs">Year</Label>
                  <Input
                    id="manual-year"
                    type="number"
                    value={manualYear}
                    onChange={(e) => setManualYear(e.target.value)}
                    placeholder={String(def?.appliedYear ?? "")}
                    data-testid="input-manual-year"
                  />
                </div>
                <div>
                  <Label htmlFor="manual-value" className="text-xs">Value ({def?.unit})</Label>
                  <Input
                    id="manual-value"
                    type="number"
                    step="any"
                    value={manualValue}
                    onChange={(e) => setManualValue(e.target.value)}
                    data-testid="input-manual-value"
                  />
                </div>
                <div className="flex items-end">
                  <Button
                    className="w-full"
                    disabled
                    title={OPERATOR_ONLY_REASON}
                    data-testid="button-save-manual"
                  >
                    Save & apply
                  </Button>
                </div>
              </div>
              <Textarea
                value={manualNote}
                onChange={(e) => setManualNote(e.target.value)}
                placeholder="Optional note (source, rationale)…"
                rows={2}
                data-testid="input-manual-note"
              />
            </fieldset>

            <Separator />
            <div className="space-y-2">
              <h3 className="text-sm font-semibold">Historical series</h3>
              <div className="max-h-56 overflow-y-auto rounded-md border">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Year</TableHead>
                      <TableHead>Value</TableHead>
                      <TableHead>Source</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {[...detail.series].reverse().map((pt) => (
                      <TableRow key={pt.year} data-testid={`row-series-${pt.year}`}>
                        <TableCell>{pt.year}</TableCell>
                        <TableCell className="font-mono">
                          {formatValue(pt.value, def?.decimals ?? 2)}
                        </TableCell>
                        <TableCell className="text-xs text-muted-foreground">
                          {pt.overridden ? (
                            <span className="text-primary">{pt.source}</span>
                          ) : (
                            pt.source
                          )}
                          {pt.asOfDate ? ` · as of ${pt.asOfDate}` : ""}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </div>

            {decided.length > 0 && (
              <>
                <Separator />
                <div className="space-y-2">
                  <h3 className="text-sm font-semibold">Decision history</h3>
                  <div className="space-y-1">
                    {decided.slice(0, 10).map((p) => (
                      <div
                        key={p.id}
                        className="flex items-center justify-between text-xs text-muted-foreground"
                        data-testid={`history-${p.id}`}
                      >
                        <span>
                          {p.year}: {formatValue(p.value, def?.decimals ?? 2)} ({p.source})
                        </span>
                        <Badge variant={p.status === "approved" ? "default" : "secondary"}>
                          {p.status}
                        </Badge>
                      </div>
                    ))}
                  </div>
                </div>
              </>
            )}
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { Slider } from "@/components/ui/slider";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Activity, Globe, Layers, BarChart3, TrendingUp, TrendingDown, ArrowUpDown, Beaker } from "lucide-react";
import { DownloadDataButton } from "@/components/download-data-button";
import { earningsYieldGapPp, gordonBaselinePct, displayDiagnostic } from "@/lib/valuation-claims";
import { QueryReadErrors } from "@/components/query-read-errors";
import { BacktestSummary, fetchBacktest } from "@/components/backtest-summary";
import type { BacktestResponse } from "@shared/backtest";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ReferenceLine,
  ComposedChart,
  Bar,
} from "recharts";

interface DecarbGapSummary {
  projectedRate: number;
  medianImpliedRate: number;
  meanImpliedRate: number;
  companyCount: number;
  positiveSignalCount: number;
  negativeSignalCount: number;
  distribution: Array<{ bucket: string; count: number; midpoint: number }>;
  topCompanies: CompanyGap[];
  bottomCompanies: CompanyGap[];
}

interface CompanyGap {
  companyId: number;
  companyName: string;
  sector: string | null;
  subSector: string | null;
  industry: string | null;
  pe: number;
  impliedGrowth: number;
  peerMedianGrowth: number;
  impliedDecarbRate: number;
  gap: number;
  score: number;
}

interface SDGGrowthPoint {
  cleanPE: number;
  dirtyPE: number;
  date: string;
  impliedDecarbRate: number;
  impliedCarbonPrice: number;
  impliedTemperature: number;
  cleanCount: number;
  dirtyCount: number;
}

interface DecarbTercilePoint {
  bestTercilePE: number;
  worstTercilePE: number;
  date: string;
  impliedDecarbRate: number;
  impliedCarbonPrice: number;
  impliedTemperature: number;
  bestTercileCompanyCount: number;
  worstTercileCompanyCount: number;
}

interface CarbonPricePoint {
  bottomTercilePeRatio: number;
  topTercilePeRatio: number;
  date: string;
  impliedCarbonPrice: number;
  impliedDecarbRate: number;
  impliedTemperature: number;
  topTercileCompanyCount: number;
  bottomTercileCompanyCount: number;
}

interface BacktestPoint {
  date: string;
  benchmarkReturn: number;
  portfolioReturn: number;
  benchmarkCumulative: number;
  portfolioCumulative: number;
  activeReturn: number;
  trackingError: number;
  overweightCount: number;
  underweightCount: number;
}

interface UploadRecord {
  id: number;
  status: string;
}

interface DimensionsData {
  sectors: string[];
  geographies: string[];
}

type ScoringMethod = "absolute" | "sector_relative" | "sub_sector_relative" | "industry_relative";
type MeasureType = "carbon_intensity" | "sdg_alignment" | "decarb_ambition";

const SCORING_METHODS: { value: ScoringMethod; label: string }[] = [
  { value: "absolute", label: "Absolute" },
  { value: "sector_relative", label: "Sector-Relative" },
  { value: "sub_sector_relative", label: "Sub-Sector" },
  { value: "industry_relative", label: "Industry" },
];

const MEASURE_TYPES: { value: MeasureType; label: string; description: string }[] = [
  { value: "carbon_intensity", label: "Carbon Intensity", description: "Low vs high carbon intensity P/E differential" },
  { value: "sdg_alignment", label: "SDG Alignment", description: "SDG-clean vs SDG-dirty growth differential" },
  { value: "decarb_ambition", label: "Decarb Ambition", description: "Best vs worst decarbonization target P/E differential" },
];

const COLORS = {
  projected: "hsl(168, 76%, 36%)",
  implied: "hsl(220, 70%, 50%)",
  positive: "hsl(168, 76%, 36%)",
  negative: "hsl(0, 70%, 50%)",
  benchmark: "hsl(var(--muted-foreground))",
  portfolio: "hsl(168, 76%, 36%)",
  valuation: "hsl(260, 60%, 55%)",
  trackingError: "hsl(30, 80%, 50%)",
  gapFill: "hsl(168, 76%, 36%)",
};

interface TimeSeriesDataPoint {
  date: number;
  dateLabel: string;
  impliedRate?: number | null;
}

function formatDateLabel(timestamp: number): string {
  const d = new Date(timestamp);
  return d.toLocaleDateString("en-US", { month: "short", year: "numeric" });
}

function formatDateStr(dateStr: string): string {
  const d = new Date(dateStr);
  return d.toLocaleDateString("en-US", { month: "short", year: "numeric" });
}

export default function DecarbGapSignal() {
  const [scoringMethod, setScoringMethod] = useState<ScoringMethod>("sector_relative");
  const [geography, setGeography] = useState<string>("all");
  const [trackingErrorLimit, setTrackingErrorLimit] = useState(2);
  const [measure, setMeasure] = useState<MeasureType>("sdg_alignment");

  const geoParam = geography !== "all" ? `&geography=${encodeURIComponent(geography)}` : "";
  const methodParam = `method=${scoringMethod}`;

  const { data: dimensions } = useQuery<DimensionsData>({
    queryKey: ["/api/cv/dimensions"],
  });

  const { data: uploads } = useQuery<UploadRecord[]>({
    queryKey: ["/api/cv/uploads"],
  });

  const uploadId = uploads?.find((u) => u.status === "completed")?.id;

  const { data: summary } = useQuery<DecarbGapSummary>({
    queryKey: ["/api/cv/decarb-gap/summary", scoringMethod, geography],
    queryFn: async () => {
      const res = await fetch(`/api/cv/decarb-gap/summary?${methodParam}${geoParam}`, { credentials: "include" });
      if (!res.ok) throw new Error("Failed to fetch summary");
      return res.json();
    },
    enabled: !!uploadId,
  });

  const { data: carbonPriceData, isLoading: loadingCP } = useQuery<CarbonPricePoint[]>({
    queryKey: ["/api/cv/carbon-price", scoringMethod, geography, uploadId],
    queryFn: async () => {
      const res = await fetch(`/api/cv/carbon-price?uploadId=${uploadId}&${methodParam}&includeScope3=false&winsorize=true&inferenceMethod=carbon_intensity${geoParam}`, { credentials: "include" });
      if (!res.ok) throw new Error("Company valuation groups unavailable");
      return res.json();
    },
    enabled: !!uploadId,
  });

  const { data: sdgData, isLoading: loadingSDG } = useQuery<SDGGrowthPoint[]>({
    queryKey: ["/api/cv/sdg-growth", geography],
    queryFn: async () => {
      const res = await fetch(`/api/cv/sdg-growth?costOfEquity=0.08${geoParam}`, { credentials: "include" });
      if (!res.ok) throw new Error("SDG valuation groups unavailable");
      return res.json();
    },
    enabled: !!uploadId,
  });

  const { data: decarbTercileData, isLoading: loadingDecarb } = useQuery<DecarbTercilePoint[]>({
    queryKey: ["/api/cv/decarb-terciles", scoringMethod, geography],
    queryFn: async () => {
      const res = await fetch(`/api/cv/decarb-terciles?${methodParam}&costOfEquity=0.08${geoParam}`, { credentials: "include" });
      if (!res.ok) throw new Error("Target valuation groups unavailable");
      return res.json();
    },
    enabled: !!uploadId,
  });

  const backtestSignal = measure === "carbon_intensity" ? "carbon_intensity"
    : measure === "sdg_alignment" ? "sdg_exposure"
    : measure === "decarb_ambition" ? "decarb_ambition"
    : "decarb_gap";

  const compareGap = backtestSignal !== "decarb_gap";
  const { data: backtestResponse, isLoading: loadingBacktest, error: backtestError } = useQuery<BacktestResponse>({
    queryKey: ["/api/cv/backtest", backtestSignal, trackingErrorLimit, scoringMethod, geography],
    queryFn: async () => {
      return fetchBacktest(`/api/cv/backtest?signal=${backtestSignal}&trackingError=${trackingErrorLimit}&trackingErrorUnit=percent&method=${compareGap ? "absolute" : scoringMethod}${geoParam}`);
    },
    enabled: !!uploadId,
  });

  const { data: valuationBacktestResponse, isLoading: loadingValBacktest, error: valuationBacktestError } = useQuery<BacktestResponse>({
    queryKey: ["/api/cv/backtest", "valuation", "decarb_gap", trackingErrorLimit, scoringMethod, geography],
    queryFn: async () => {
      return fetchBacktest(`/api/cv/backtest?signal=decarb_gap&trackingError=${trackingErrorLimit}&trackingErrorUnit=percent&${methodParam}${geoParam}`);
    },
    enabled: !!uploadId && compareGap,
  });
  const backtestData = backtestResponse?.series;
  const valuationBacktestData = compareGap ? valuationBacktestResponse?.series : undefined;

  const selectedMeasureData = useMemo(() => {
    if (measure === "carbon_intensity") return carbonPriceData;
    if (measure === "sdg_alignment") return sdgData;
    if (measure === "decarb_ambition") return decarbTercileData;
    return null;
  }, [measure, carbonPriceData, sdgData, decarbTercileData]);

  const latestImpliedRate = useMemo(() => {
    if (!selectedMeasureData || selectedMeasureData.length === 0) return null;
    const last = selectedMeasureData[selectedMeasureData.length - 1];
    if ("cleanPE" in last) return earningsYieldGapPp(last.cleanPE, last.dirtyPE);
    if ("bestTercilePE" in last) return earningsYieldGapPp(last.bestTercilePE, last.worstTercilePE);
    return earningsYieldGapPp(last.bottomTercilePeRatio, last.topTercilePeRatio);
  }, [selectedMeasureData]);


  const chartData = useMemo(() => {
    const dateMap = new Map<number, TimeSeriesDataPoint>();

    if (selectedMeasureData) {
      for (const pt of selectedMeasureData) {
        const ts = new Date(pt.date).getTime();
        const existing = dateMap.get(ts);
        const impliedRate = "cleanPE" in pt ? earningsYieldGapPp(pt.cleanPE, pt.dirtyPE)
          : "bestTercilePE" in pt ? earningsYieldGapPp(pt.bestTercilePE, pt.worstTercilePE)
          : earningsYieldGapPp(pt.bottomTercilePeRatio, pt.topTercilePeRatio);
        if (existing) {
          existing.impliedRate = impliedRate;
        } else {
          dateMap.set(ts, {
            date: ts,
            dateLabel: formatDateLabel(ts),
            impliedRate,
          });
        }
      }
    }

    return Array.from(dateMap.values()).sort((a, b) => a.date - b.date);
  }, [selectedMeasureData]);

  const loadingMeasure = (measure === "carbon_intensity" && loadingCP) ||
    (measure === "sdg_alignment" && loadingSDG) ||
    (measure === "decarb_ambition" && loadingDecarb);
  const loadingTS = loadingMeasure;
  const hasChartData = chartData.some(d => d.impliedRate != null);
  const hasData = !!summary && summary.companyCount > 0;

  function computeStats(data: BacktestPoint[] | undefined) {
    if (!data || data.length === 0) return null;
    const last = data[data.length - 1];
    const totalActiveReturn = (last.portfolioCumulative / last.benchmarkCumulative - 1) * 100;
    const annualizedActive = data.length > 12
      ? (Math.pow(last.portfolioCumulative / last.benchmarkCumulative, 12 / data.length) - 1) * 100
      : totalActiveReturn;
    const avgGreen = Math.round(data.reduce((s, d) => s + d.overweightCount, 0) / data.length);
    const avgBrown = Math.round(data.reduce((s, d) => s + d.underweightCount, 0) / data.length);
    return {
      totalActive: totalActiveReturn,
      annualizedActive,
      finalTE: last.trackingError * 100,
      benchmarkTotal: (last.benchmarkCumulative - 1) * 100,
      portfolioTotal: (last.portfolioCumulative - 1) * 100,
      avgGreen,
      avgBrown,
      months: data.length,
    };
  }

  const backtestStats = useMemo(() => computeStats(backtestData), [backtestData]);
  const valBacktestStats = useMemo(() => computeStats(valuationBacktestData), [valuationBacktestData]);

  const backtestChartData = useMemo(() => {
    if (!backtestData && !valuationBacktestData) return [];
    const signalMap = new Map<string, BacktestPoint>();
    const valMap = new Map<string, BacktestPoint>();
    if (backtestData) {
      for (const d of backtestData) signalMap.set(d.date, d);
    }
    if (valuationBacktestData) {
      for (const d of valuationBacktestData) valMap.set(d.date, d);
    }
    const allDates = Array.from(new Set([...Array.from(signalMap.keys()), ...Array.from(valMap.keys())])).sort();
    return allDates.map((date) => {
      const sd = signalMap.get(date);
      const vd = valMap.get(date);
      const bmSource = sd || vd;
      return {
        date,
        benchmark: bmSource ? Math.round((bmSource.benchmarkCumulative - 1) * 10000) / 100 : undefined,
        portfolio: sd ? Math.round((sd.portfolioCumulative - 1) * 10000) / 100 : undefined,
        valuation: vd ? Math.round((vd.portfolioCumulative - 1) * 10000) / 100 : undefined,
        activeReturn: sd ? Math.round(sd.activeReturn * 10000) / 100 : undefined,
        trackingError: sd ? Math.round(sd.trackingError * 10000) / 100 : undefined,
      };
    });
  }, [backtestData, valuationBacktestData]);

  const TimeSeriesChartTooltip = ({ active, payload, label }: any) => {
    if (!active || !payload || payload.length === 0) return null;
    return (
      <div className="bg-popover border rounded-md p-3 shadow-md text-sm">
        <p className="font-medium text-foreground mb-2">{formatDateLabel(label)}</p>
        {payload.map((entry: any) => (
          <div key={entry.dataKey} className="flex items-center justify-between gap-4">
            <span className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-full inline-block" style={{ backgroundColor: entry.color }} />
              <span className="text-muted-foreground">{entry.name}</span>
            </span>
            <span className="font-medium tabular-nums" style={{ color: entry.color }}>
              {displayDiagnostic(entry.value, " pp")}
            </span>
          </div>
        ))}
      </div>
    );
  };

  const BacktestTooltip = ({ active, payload, label }: any) => {
    if (!active || !payload || payload.length === 0) return null;
    return (
      <div className="bg-popover border rounded-md p-3 shadow-md text-sm">
        <p className="font-medium text-foreground mb-2">{label}</p>
        {payload.map((entry: any) => (
          <div key={entry.dataKey} className="flex items-center justify-between gap-4">
            <span className="flex items-center gap-1.5">
              <span className="w-2.5 h-2.5 rounded-full inline-block" style={{ backgroundColor: entry.color }} />
              <span className="text-muted-foreground">{entry.name}</span>
            </span>
            <span className="font-medium tabular-nums" style={{ color: entry.color }}>
              {entry.value?.toFixed(2)}%
            </span>
          </div>
        ))}
      </div>
    );
  };

  const measureInfo = MEASURE_TYPES.find(m => m.value === measure);

  const timeseriesDownloadRows = chartData.map((d) => ({
    "Date": formatDateLabel(d.date),
    [`Group earnings-yield gap - ${measureInfo?.label ?? "Measure"} (pp)`]: d.impliedRate,
  }));

  const cumulativeReturnDownloadRows = backtestChartData.map((d) => ({
    "Date": d.date,
    "Benchmark Cumulative Return (%)": d.benchmark,
    [`${measureInfo?.label ?? "Measure"}-Driven Cumulative Return (%)`]: d.portfolio,
    ...(compareGap ? { "Legacy peer-yield ranking cumulative return (%)": d.valuation } : {}),
  }));

  const activeReturnDownloadRows = backtestChartData.map((d) => ({
    "Date": d.date,
    "Active Return (%)": d.activeReturn,
    "Tracking Error (ann. %)": d.trackingError,
  }));

  return (
    <div className="p-4 space-y-4 max-w-full" data-testid="page-decarb-gap-signal">
      <QueryReadErrors prefix="/api/cv" />
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight" data-testid="text-page-title">
            Peer-Relative Valuation Diagnostics
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Gordon steady-state baselines and peer-relative earnings-yield gaps — not decarbonization estimates
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-2">
            <Beaker className="h-4 w-4 text-muted-foreground" />
            <Select value={measure} onValueChange={(v) => setMeasure(v as MeasureType)}>
              <SelectTrigger className="w-[180px]" data-testid="select-measure">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {MEASURE_TYPES.map((m) => (
                  <SelectItem key={m.value} value={m.value} data-testid={`option-measure-${m.value}`}>
                    {m.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="flex items-center gap-2">
            <Layers className="h-4 w-4 text-muted-foreground" />
            <Select value={scoringMethod} onValueChange={(v) => setScoringMethod(v as ScoringMethod)}>
              <SelectTrigger className="w-[160px]" data-testid="select-scoring-method">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {SCORING_METHODS.map((m) => (
                  <SelectItem key={m.value} value={m.value} data-testid={`option-method-${m.value}`}>
                    {m.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="flex items-center gap-2">
            <Globe className="h-4 w-4 text-muted-foreground" />
            <Select value={geography} onValueChange={setGeography}>
              <SelectTrigger className="w-[180px]" data-testid="select-geography">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all" data-testid="option-geo-all">All Geographies</SelectItem>
                {dimensions?.geographies?.map((geo) => (
                  <SelectItem key={geo} value={geo} data-testid={`option-geo-${geo.toLowerCase().replace(/\s+/g, "-")}`}>
                    {geo.charAt(0) + geo.slice(1).toLowerCase()}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>

      {!uploadId && (
        <Card className="p-8 flex flex-col items-center justify-center text-muted-foreground">
          <Activity className="h-10 w-10 mb-3 opacity-40" />
          <p className="text-sm">No company dataset is available. Import and review require the operator CLI.</p>
        </Card>
      )}

      {uploadId && (
        <>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
            <Card className="p-4">
              <div className="flex items-center justify-between gap-2 mb-2">
                <span className="text-xs text-muted-foreground font-medium">Physical decarbonization rate</span>
                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS.projected }} />
              </div>
              <p className="text-2xl font-bold tabular-nums" data-testid="text-projected-rate">
                Unavailable
              </p>
              <p className="text-xs text-muted-foreground">Not inferred from valuations</p>
            </Card>
            <Card className="p-4">
              <div className="flex items-center justify-between gap-2 mb-2">
                <span className="text-xs text-muted-foreground font-medium">Group earnings-yield gap ({measureInfo?.label})</span>
                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS.implied }} />
              </div>
              <p className="text-2xl font-bold tabular-nums" data-testid="text-implied-rate">
                {displayDiagnostic(latestImpliedRate, " pp")}
              </p>
              <p className="text-xs text-muted-foreground">First-minus-second group Gordon baseline gap</p>
            </Card>
            <Card className="p-4">
              <div className="flex items-center justify-between gap-2 mb-2">
                <span className="text-xs text-muted-foreground font-medium">Physical vs. valuation gap</span>
                <ArrowUpDown className="h-3.5 w-3.5 text-muted-foreground" />
              </div>
              <p className="text-2xl font-bold tabular-nums" data-testid="text-gap">
                Withheld
              </p>
              <p className="text-xs text-muted-foreground">Definitions are not comparable</p>
            </Card>
            <Card className="p-4">
              <div className="flex items-center justify-between gap-2 mb-2">
                <span className="text-xs text-muted-foreground font-medium">Companies Scored</span>
              </div>
              <p className="text-2xl font-bold tabular-nums" data-testid="text-company-count">
                {summary ? summary.companyCount : "\u2014"}
              </p>
              <p className="text-xs text-muted-foreground">
                Legacy eligible-company count; not verified identity coverage
              </p>
            </Card>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <Card className="p-4" data-testid="card-gap-distribution">
              <div className="flex items-start justify-between gap-2 mb-4">
                <div>
                  <h2 className="text-base font-semibold mb-1">Physical-gap distribution withheld</h2>
                  <p className="text-xs text-muted-foreground">
                    A global physical reduction rate cannot be subtracted from a valuation earnings-yield gap.
                  </p>
                </div>
              </div>
              <p className="text-sm text-muted-foreground">
                Temperature, carbon-price and net-zero outputs are unavailable. No numeric substitutes or physical-gap downloads are provided.
                Company diagnostics below show only the legacy endpoint&apos;s selected subset, not a full-universe ranking.
              </p>
            </Card>

            <Card className="p-4" data-testid="card-gap-timeseries">
              <div className="flex items-start justify-between gap-2 mb-4">
                <div>
                  <h2 className="text-base font-semibold mb-1">Group earnings-yield gap over time</h2>
                  <p className="text-xs text-muted-foreground">
                    {measureInfo?.description}. Descriptive valuation difference only.
                  </p>
                </div>
                <DownloadDataButton
                  filename="group-earnings-yield-gap-over-time"
                  sheetName="Group valuation gap"
                  rows={timeseriesDownloadRows}
                  testId="button-download-gap-timeseries"
                />
              </div>
              {loadingTS ? (
                <Skeleton className="w-full h-[300px]" />
              ) : !hasChartData ? (
                <div className="flex items-center justify-center h-[300px] text-muted-foreground text-sm">
                  No time series data available
                </div>
              ) : (
                <ResponsiveContainer width="100%" height={300}>
                  <ComposedChart data={chartData} margin={{ top: 5, right: 20, left: 10, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" className="opacity-30" />
                    <XAxis
                      dataKey="date"
                      tick={{ fontSize: 10 }}
                      tickFormatter={formatDateLabel}
                      type="number"
                      domain={["dataMin", "dataMax"]}
                      scale="time"
                      interval="preserveStartEnd"
                    />
                    <YAxis
                      tick={{ fontSize: 10 }}
                      tickFormatter={(v: number) => `${v.toFixed(1)}%`}
                      label={{ value: "Earnings-yield gap (pp)", angle: -90, position: "insideLeft", style: { fontSize: 11, fill: "hsl(var(--muted-foreground))" } }}
                    />
                    <Tooltip content={<TimeSeriesChartTooltip />} />
                    <Legend wrapperStyle={{ fontSize: 11 }} />
                    <ReferenceLine y={0} stroke="hsl(var(--muted-foreground))" strokeDasharray="4 4" strokeOpacity={0.5} />
                    <Line
                      dataKey="impliedRate"
                      name={`Earnings-yield gap (${measureInfo?.label})`}
                      stroke={COLORS.implied}
                      strokeWidth={2}
                      dot={false}
                      type="monotone"
                      connectNulls
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              )}
            </Card>
          </div>

          {hasData && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              <Card className="p-4" data-testid="card-top-companies">
                <div className="flex items-center gap-2 mb-3">
                  <TrendingUp className="h-4 w-4 text-green-600 dark:text-green-400" />
                  <h2 className="text-sm font-semibold">Legacy selected companies — first subset</h2>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-xs">
                    <thead>
                      <tr className="border-b text-muted-foreground">
                        <th className="text-left py-1.5 pr-2">Company</th>
                        <th className="text-left py-1.5 pr-2">Sector</th>
                        <th className="text-right py-1.5 pr-2">P/E</th>
                        <th className="text-right py-1.5 pr-2">Gordon baseline</th>
                        <th className="text-right py-1.5">Peer earnings-yield gap</th>
                      </tr>
                    </thead>
                    <tbody>
                      {summary?.topCompanies.map((c) => (
                        <tr key={c.companyId} className="border-b border-border/50">
